/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateAllergyChangePriority exports=evaluateAllergyChangePriority */
const __aivicBundle_8_evaluateAllergyChangePriority = (() => {
  function evaluateAllergyChangePriority(input: {
    current_allergen_list: Array<{
      allergen_id: string;
      allergen_name: string;
      allergen_code: string;
    }>;
    previous_allergen_list: Array<{
      allergen_id: string;
      allergen_name: string;
      allergen_code: string;
    }>;
    evaluation_timestamp: Date;
    user_id: string;
  }): {
    change_status: 'no_change' | 'added' | 'removed' | 'modified';
    is_modified: boolean;
    priority_score: number;
    system_log_message: string;
    added_allergens: string[];
    removed_allergens: string[];
    allergen_count_current: number;
    allergen_count_previous: number;
  } {
    if (
      input.evaluation_timestamp === undefined ||
      input.evaluation_timestamp === null ||
      String(input.evaluation_timestamp).trim() === ''
    ) {
      throw new Error('evaluation_timestamp is required');
    }
  
    const currentIds = new Set(
      input.current_allergen_list.map((a) => a.allergen_id)
    );
    const previousIds = new Set(
      input.previous_allergen_list.map((a) => a.allergen_id)
    );
  
    const currentIdToName = new Map(
      input.current_allergen_list.map((a) => [a.allergen_id, a.allergen_name])
    );
    const previousIdToName = new Map(
      input.previous_allergen_list.map((a) => [a.allergen_id, a.allergen_name])
    );
  
    const added: string[] = [];
    const removed: string[] = [];
  
    for (const id of currentIds) {
      if (!previousIds.has(id)) {
        const name = currentIdToName.get(id);
        if (name) {
          added.push(name);
        }
      }
    }
  
    for (const id of previousIds) {
      if (!currentIds.has(id)) {
        const name = previousIdToName.get(id);
        if (name) {
          removed.push(name);
        }
      }
    }
  
    const allergen_count_current = input.current_allergen_list.length;
    const allergen_count_previous = input.previous_allergen_list.length;
  
    let change_status: 'no_change' | 'added' | 'removed' | 'modified' =
      'no_change';
    let priority_score = 0;
    let system_log_message = '';
  
    const evaluationTimestampStr = input.evaluation_timestamp.toISOString();
  
    if (added.length === 0 && removed.length === 0) {
      change_status = 'no_change';
      priority_score = 0;
      system_log_message = `アレルギー情報に変更がないため、優先度スコアは0です。ユーザーID: ${input.user_id}, 評価時刻: ${evaluationTimestampStr}`;
    } else if (added.length > 0 && removed.length === 0) {
      change_status = 'added';
      priority_score = 10 * added.length;
      system_log_message = `新しいアレルギー情報が追加されました: ${added.join(', ')}。優先度スコア: ${priority_score}, 評価時刻: ${evaluationTimestampStr}`;
    } else if (added.length === 0 && removed.length > 0) {
      change_status = 'removed';
      priority_score = 5 * removed.length;
      system_log_message = `アレルギー情報が削除されました: ${removed.join(', ')}。優先度スコア: ${priority_score}, 評価時刻: ${evaluationTimestampStr}`;
    } else {
      change_status = 'modified';
      priority_score = 10 * added.length + 5 * removed.length;
      system_log_message = `アレルギー情報が変更されました。追加: ${added.join(', ')}, 削除: ${removed.join(', ')}。優先度スコア: ${priority_score}, 評価時刻: ${evaluationTimestampStr}`;
    }
  
    return {
      change_status,
      is_modified: added.length > 0 || removed.length > 0,
      priority_score,
      system_log_message,
      added_allergens: added,
      removed_allergens: removed,
      allergen_count_current,
      allergen_count_previous,
    };
  }
  return { evaluateAllergyChangePriority };
})();
export const evaluateAllergyChangePriority = __aivicBundle_8_evaluateAllergyChangePriority.evaluateAllergyChangePriority;
/* AIVIC_FUNCTION_BUNDLE_END owner=evaluateAllergyChangePriority */

/* AIVIC_FUNCTION_BUNDLE_START owner=detectConflictingMeals exports=detectConflictingMeals */
const __aivicBundle_9_detectConflictingMeals = (() => {
  function detectConflictingMeals(
    newDietaryRestriction: {
      restrictionId: string;
      restrictionName: string;
      allergenList: string[];
      createdAt: Date;
    },
    pastMealHistory: Array<{
      mealId: string;
      mealName: string;
      ingredients: string[];
      createdAt: Date;
    }>
  ): {
    conflictingMealCount: number;
    conflictingMeals: Array<{
      mealId: string;
      mealName: string;
      conflictingIngredients: string[];
      restrictionName: string;
      riskLevel: "低" | "中" | "高";
      importanceScore: number;
    }>;
    detectionComplete: boolean;
    detectedAt: string;
  } {
    if (
      !newDietaryRestriction.restrictionId ||
      String(newDietaryRestriction.restrictionId).trim() === ""
    ) {
      throw new Error("restrictionId is required");
    }
  
    const conflictingMeals: Array<{
      mealId: string;
      mealName: string;
      conflictingIngredients: string[];
      restrictionName: string;
      riskLevel: "低" | "中" | "高";
      importanceScore: number;
    }> = [];
  
    const allergenListLower = newDietaryRestriction.allergenList.map((a) =>
      a.toLowerCase()
    );
  
    for (const meal of pastMealHistory) {
      const conflictingIngredients: string[] = [];
  
      for (const ingredient of meal.ingredients) {
        const ingredientLower = ingredient.toLowerCase();
        for (const allergen of allergenListLower) {
          if (ingredientLower.includes(allergen)) {
            conflictingIngredients.push(ingredient);
            break;
          }
        }
      }
  
      if (conflictingIngredients.length > 0) {
        const daysDifference = Math.floor(
          (newDietaryRestriction.createdAt.getTime() - meal.createdAt.getTime()) /
            (1000 * 60 * 60 * 24)
        );
  
        let riskLevel: "低" | "中" | "高" = "中";
        if (daysDifference <= 7) {
          riskLevel = "高";
        } else if (daysDifference > 30) {
          riskLevel = "低";
        }
  
        const importanceScore = Math.min(
          10,
          Math.max(
            1,
            5 +
              conflictingIngredients.length -
              Math.floor(daysDifference / 10)
          )
        );
  
        conflictingMeals.push({
          mealId: meal.mealId,
          mealName: meal.mealName,
          conflictingIngredients,
          restrictionName: newDietaryRestriction.restrictionName,
          riskLevel,
          importanceScore,
        });
      }
    }
  
    return {
      conflictingMealCount: conflictingMeals.length,
      conflictingMeals,
      detectionComplete: true,
      detectedAt: new Date().toISOString(),
    };
  }
  return { detectConflictingMeals };
})();
export const detectConflictingMeals = __aivicBundle_9_detectConflictingMeals.detectConflictingMeals;
