/* AIVIC_FUNCTION_BUNDLE_START owner=accumulateMealEvaluationData exports=accumulateMealEvaluationData */
const __aivicBundle_21_accumulateMealEvaluationData = (() => {
  function accumulateMealEvaluationData(
    evaluationRecords: Array<{
      family_member_id: string;
      dish_id: string;
      evaluation_date: string;
      satisfaction_score: number;
      completion_rate: number;
      preference_info: string;
    }>
  ): EvaluationDataset {
    const familyMembersMap: {
      [key: string]: {
        member_id: string;
        records_count: number;
        records: Array<{
          family_member_id: string;
          dish_id: string;
          evaluation_date: string;
          satisfaction_score: number;
          completion_rate: number;
          preference_info: string;
          sequence_order: number;
        }>;
      };
    } = {};
  
    // グループ化と時系列ソート
    for (const record of evaluationRecords) {
      const memberId = record.family_member_id;
  
      if (!familyMembersMap[memberId]) {
        familyMembersMap[memberId] = {
          member_id: memberId,
          records_count: 0,
          records: [],
        };
      }
  
      familyMembersMap[memberId].records.push({
        family_member_id: record.family_member_id,
        dish_id: record.dish_id,
        evaluation_date: record.evaluation_date,
        satisfaction_score: record.satisfaction_score,
        completion_rate: record.completion_rate,
        preference_info: record.preference_info,
        sequence_order: 0, // 後で設定
      });
    }
  
    // 各家族成員のレコードを日付でソートし、sequence_order を設定
    for (const memberId in familyMembersMap) {
      const memberData = familyMembersMap[memberId];
      memberData.records.sort(
        (a, b) =>
          new Date(a.evaluation_date).getTime() -
          new Date(b.evaluation_date).getTime()
      );
  
      memberData.records.forEach((record, index) => {
        record.sequence_order = index + 1;
      });
  
      memberData.records_count = memberData.records.length;
    }
  
    const totalRecords = evaluationRecords.length;
    const aggregationTimestamp = new Date().toISOString();
  
    return {
      dataset_version: '1.0',
      total_records: totalRecords,
      family_members: familyMembersMap,
      aggregation_timestamp: aggregationTimestamp,
      data_quality_score: 100,
    };
  }
  return { accumulateMealEvaluationData };
})();
export const accumulateMealEvaluationData = __aivicBundle_21_accumulateMealEvaluationData.accumulateMealEvaluationData;
/* AIVIC_FUNCTION_BUNDLE_END owner=accumulateMealEvaluationData */

/* AIVIC_FUNCTION_BUNDLE_START owner=mergeAndPrepareMealEvaluationData exports=mergeAndPrepareMealEvaluationData */
const __aivicBundle_22_mergeAndPrepareMealEvaluationData = (() => {
  function mergeAndPrepareMealEvaluationData(
    evaluationData: Array<{
      familyMemberId: string;
      dishName: string;
      evaluationDateTime: Date;
      evaluationScore: number;
      remarks: string;
    }>
  ): {
    mergedRecords: Array<MergedEvaluationRecord>;
    duplicateRecordCount: number;
    preferenceReadyFlag: boolean;
    processingStatus: string;
  } {
    const mergedMap = new Map<string, MergedEvaluationRecord>();
  
    for (const record of evaluationData) {
      const key = `${record.familyMemberId}|${record.dishName}`;
  
      if (mergedMap.has(key)) {
        const existing = mergedMap.get(key)!;
        existing.evaluationHistory.push({
          evaluationScore: record.evaluationScore,
          remarks: record.remarks,
          evaluationDateTime: record.evaluationDateTime,
        });
        existing.evaluationHistory.sort(
          (a, b) =>
            a.evaluationDateTime.getTime() - b.evaluationDateTime.getTime()
        );
        existing.evaluationDateTime =
          existing.evaluationHistory[
            existing.evaluationHistory.length - 1
          ].evaluationDateTime;
        existing.evaluationScore =
          existing.evaluationHistory[existing.evaluationHistory.length - 1]
            .evaluationScore;
        existing.remarks =
          existing.evaluationHistory[existing.evaluationHistory.length - 1]
            .remarks;
      } else {
        const newRecord: MergedEvaluationRecord = {
          familyMemberId: record.familyMemberId,
          dishName: record.dishName,
          evaluationDateTime: record.evaluationDateTime,
          evaluationScore: record.evaluationScore,
          remarks: record.remarks,
          evaluationHistory: [
            {
              evaluationScore: record.evaluationScore,
              remarks: record.remarks,
              evaluationDateTime: record.evaluationDateTime,
            },
          ],
        };
        mergedMap.set(key, newRecord);
      }
    }
  
    const mergedRecords = Array.from(mergedMap.values());
    const duplicateRecordCount = evaluationData.length - mergedRecords.length;
    const preferenceReadyFlag = mergedRecords.length > 0;
    const processingStatus = "completed";
  
    return {
      mergedRecords,
      duplicateRecordCount,
      preferenceReadyFlag,
      processingStatus,
    };
  }
  return { mergeAndPrepareMealEvaluationData };
})();
export const mergeAndPrepareMealEvaluationData = __aivicBundle_22_mergeAndPrepareMealEvaluationData.mergeAndPrepareMealEvaluationData;
/* AIVIC_FUNCTION_BUNDLE_END owner=mergeAndPrepareMealEvaluationData */

