const __aivicBundle_23_validateMealEvaluationScore = (() => {
  interface ValidateMealEvaluationScoreInput {
    user_id: string;
    meal_id: string;
    evaluation_score: number;
    timestamp: string;
    family_member_id: string;
  }
  
  interface ValidateMealEvaluationScoreQualityCheckLog {
    score_in_range: boolean;
    user_id: string;
    meal_id: string;
    timestamp: string;
    family_member_id: string;
    invalid_score_value?: number;
    valid_range?: string;
  }
  
  interface ValidateMealEvaluationScoreResult {
    is_valid: boolean;
    error_code: string | null;
    error_message: string | null;
    quality_check_log: ValidateMealEvaluationScoreQualityCheckLog;
  }
  
   function validateMealEvaluationScore(
    input: ValidateMealEvaluationScoreInput
  ): ValidateMealEvaluationScoreResult {
    const MIN_SCORE = 1;
    const MAX_SCORE = 5;
    const VALID_RANGE = "1-5";
  
    const { user_id, meal_id, evaluation_score, timestamp, family_member_id } =
      input;
  
    const isScoreInRange =
      evaluation_score >= MIN_SCORE && evaluation_score <= MAX_SCORE;
  
    if (isScoreInRange) {
      return {
        is_valid: true,
        error_code: null,
        error_message: null,
        quality_check_log: {
          score_in_range: true,
          user_id,
          meal_id,
          timestamp,
          family_member_id,
        },
      };
    }
  
    return {
      is_valid: false,
      error_code: "EVAL_SCORE_OUT_OF_RANGE",
      error_message: "評価スコアが有効範囲外です",
      quality_check_log: {
        score_in_range: false,
        user_id,
        meal_id,
        timestamp,
        family_member_id,
        invalid_score_value: evaluation_score,
        valid_range: VALID_RANGE,
      },
    };
  }
  return { validateMealEvaluationScore };
})();
