/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutritionAchievementAndGaps exports=calculateNutritionAchievementAndGaps */
const __aivicBundle_28_calculateNutritionAchievementAndGaps = (() => {
  function calculateNutritionAchievementAndGaps(
    userId: string,
    nutritionItems: Array<{
      nutrition_id: string;
      nutrition_name: string;
      unit: string;
      target_value: number;
      actual_value: number;
    }>,
    analysisDate: string,
    logCallback: (log: string) => void
  ): {
    achievement_scores: Array<{
      nutrition_id: string;
      achievement_percentage: number | null;
      display_status: string;
    }>;
    improvement_gaps: Array<{
      nutrition_id: string;
      gap_value: number;
      priority_rank: number;
    }>;
    dashboard_display: Array<{
      nutrition_id: string;
      label: string;
      value_display: string;
      is_calculable: boolean;
      achievement_rate?: number;
    }>;
    status: string;
    error_count: number;
    processed_date: string;
  } {
    const achievement_scores: Array<{
      nutrition_id: string;
      achievement_percentage: number | null;
      display_status: string;
    }> = [];
  
    const improvement_gaps: Array<{
      nutrition_id: string;
      gap_value: number;
      priority_rank: number;
    }> = [];
  
    const dashboard_display: Array<{
      nutrition_id: string;
      label: string;
      value_display: string;
      is_calculable: boolean;
      achievement_rate?: number;
    }> = [];
  
    let error_count = 0;
  
    // Validate userId is present
    if (!userId || !String(userId).trim()) {
      logCallback(`警告: ユーザーID が空です。userId: ${userId}`);
      error_count++;
    }
  
    // Process each nutrition item
    for (const item of nutritionItems) {
      const { nutrition_id, nutrition_name, target_value, actual_value } = item;
  
      // Check for zero division (target_value = 0)
      if (target_value === 0) {
        error_count++;
        logCallback(
          `警告: 栄養項目 "${nutrition_name}" (${nutrition_id}) の目標値が0のため、達成度計算不可。ゼロ除算を回避しました。`
        );
  
        achievement_scores.push({
          nutrition_id,
          achievement_percentage: null,
          display_status: "計算不可",
        });
  
        dashboard_display.push({
          nutrition_id,
          label: nutrition_name,
          value_display: "計算不可",
          is_calculable: false,
        });
  
        // Skip adding to improvement_gaps for zero target
        continue;
      }
  
      // Calculate achievement percentage
      const achievement_percentage = Math.round(
        (actual_value / target_value) * 100
      );
  
      // Determine display status
      const display_status = "達成";
  
      achievement_scores.push({
        nutrition_id,
        achievement_percentage,
        display_status,
      });
  
      dashboard_display.push({
        nutrition_id,
        label: nutrition_name,
        value_display: `${achievement_percentage}%`,
        is_calculable: true,
        achievement_rate: achievement_percentage,
      });
  
      // Calculate improvement gap only if actual < target
      if (actual_value < target_value) {
        const gap_value = target_value - actual_value;
        improvement_gaps.push({
          nutrition_id,
          gap_value,
          priority_rank: 0, // Will be assigned after sorting
        });
      }
    }
  
    // Assign priority ranks to improvement gaps (sorted by gap_value descending)
    improvement_gaps.sort((a, b) => b.gap_value - a.gap_value);
    improvement_gaps.forEach((gap, index) => {
      gap.priority_rank = index + 1;
    });
  
    // Determine overall status
    const status =
      error_count > 0 ? "success_with_warnings" : "success";
  
    return {
      achievement_scores,
      improvement_gaps,
      dashboard_display,
      status,
      error_count,
      processed_date: analysisDate,
    };
  }
  return { calculateNutritionAchievementAndGaps };
})();
