const __aivicBundle_29_calculateNutritionAchievementDegree = (() => {
  function calculateNutritionAchievementDegree(
    input1: any,
    input2?: any
  ): any {
    // Case 1: Two numeric arguments (recommendedValue, actualValue)
    if (typeof input1 === 'number' && typeof input2 === 'number') {
      const recommendedValue = input1;
      const actualValue = input2;
      const achievementDegreePercentage = Math.round(
        (actualValue / recommendedValue) * 100
      );
      const excessAmount = actualValue - recommendedValue;
  
      return {
        achievementDegreePercentage,
        excessAmount,
        itemName: undefined
      };
    }
  
    // Case 2: Object with user_id, meal_records, nutrition_targets, meal_nutrients
    if (
      input1 &&
      typeof input1 === 'object' &&
      'user_id' in input1 &&
      'meal_records' in input1 &&
      'nutrition_targets' in input1
    ) {
      const { user_id, meal_records, nutrition_targets, meal_nutrients } = input1;
  
      if (!meal_records || meal_records.length === 0) {
        throw new Error('食事記録が不足しています');
      }
  
      if (!nutrition_targets || nutrition_targets.length === 0) {
        throw new Error('栄養基準値が設定されていません');
      }
  
      const analysis_date = new Date().toISOString();
      const achievement_results: any[] = [];
  
      for (const target of nutrition_targets) {
        const nutrient_id = target.nutrient_id;
        const nutrient_name = target.nutrient_name;
        const target_value = target.target_value;
  
        let actual_value = 0;
        if (meal_nutrients) {
          for (const nutrient of meal_nutrients) {
            if (nutrient.nutrient_id === nutrient_id) {
              actual_value += nutrient.actual_value || 0;
            }
          }
        }
  
        const achievement_percentage = Math.round(
          (actual_value / target_value) * 100
        );
  
        achievement_results.push({
          nutrient_id,
          nutrient_name,
          target_value,
          actual_value,
          achievement_percentage
        });
      }
  
      return {
        user_id,
        analysis_date,
        achievement_results,
        improvement_gaps: achievement_results
          .filter((r) => r.achievement_percentage < 100)
          .map((r) => ({
            nutrient_id: r.nutrient_id,
            nutrient_name: r.nutrient_name,
            gap_value: r.target_value - r.actual_value,
            priority_rank: 1
          }))
      };
    }
  
    // Case 3: Object with nutritionItems array (from plan)
    if (
      input1 &&
      typeof input1 === 'object' &&
      'nutritionItems' in input1 &&
      Array.isArray(input1.nutritionItems)
    ) {
      const { nutritionItems } = input1;
  
      const achievementDegrees = nutritionItems.map((item: any) => {
        const degree = Math.round((item.actualValue / item.targetValue) * 100);
        const status = degree >= 100 ? '達成' : '不足';
  
        return {
          itemId: item.itemId,
          itemName: item.itemName,
          degree,
          status
        };
      });
  
      const achievedCount = achievementDegrees.filter(
        (d: any) => d.status === '達成'
      ).length;
      const insufficientCount = achievementDegrees.filter(
        (d: any) => d.status === '不足'
      ).length;
  
      return {
        achievementDegrees,
        summary: {
          totalItems: nutritionItems.length,
          achievedCount,
          insufficientCount
        }
      };
    }
  
    // Case 4: Meal record with nutrition standards (error case)
    if (
      input1 &&
      typeof input1 === 'object' &&
      'userId' in input1 &&
      'mealType' in input1 &&
      input2 &&
      typeof input2 === 'object' &&
      'nutritionTargets' in input2
    ) {
      const nutritionTargets = input2.nutritionTargets;
  
      if (!nutritionTargets || Object.keys(nutritionTargets).length === 0) {
        throw new Error('栄養基準値が設定されていません');
      }
  
      return {
        success: true
      };
    }
  
    throw new Error('Invalid input format');
  }
  return { calculateNutritionAchievementDegree };
})();
export const calculateNutritionAchievementDegree = __aivicBundle_29_calculateNutritionAchievementDegree.calculateNutritionAchievementDegree;
