/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeMonthlyBudgetExceedance exports=analyzeMonthlyBudgetExceedance */
const __aivicBundle_31_analyzeMonthlyBudgetExceedance = (() => {
  function analyzeMonthlyBudgetExceedance(input: {
    userId?: string;
    yearMonth?: string;
    budgetAmount?: number;
    actualSpent?: number;
    purchaseRecords?: Array<{
      itemId?: string;
      itemName?: string;
      plannedQuantity?: number;
      actualQuantity?: number;
      standardPrice?: number;
      actualPrice?: number;
      category?: string;
    }>;
  }): {
    userId: string;
    yearMonth: string;
    budgetAmount: number;
    actualSpent: number;
    totalExceedance: number;
    exceedanceFactors: {
      quantityExceedance: number;
      priceFluctuationExceedance: number;
    };
    itemizeBreakdown: Array<{
      itemId?: string;
      itemName?: string;
      category?: string;
      quantityExceedance: number;
      priceFluctuationExceedance: number;
      totalExceedance: number;
    }>;
    riskItems: Array<{
      itemId?: string;
      itemName?: string;
      riskLevel: string;
      priceInflationRate: number;
    }>;
  } {
    // Validation
    if (!input.userId || input.userId === "") {
      throw new Error("ユーザーID は必須です");
    }
    if (!input.yearMonth || input.yearMonth === "") {
      throw new Error("年月 は必須です");
    }
    if (input.budgetAmount === undefined || input.budgetAmount < 0) {
      throw new Error("予算 は0以上の数値である必要があります");
    }
    if (input.actualSpent === undefined) {
      throw new Error("実績支出 は必須です");
    }
  
    const purchaseRecords = input.purchaseRecords || [];
    const totalExceedance = Math.max(0, input.actualSpent - input.budgetAmount);
  
    // Calculate exceedance factors
    let quantityExceedance = 0;
    let priceFluctuationExceedance = 0;
    const itemizeBreakdown: Array<{
      itemId?: string;
      itemName?: string;
      category?: string;
      quantityExceedance: number;
      priceFluctuationExceedance: number;
      totalExceedance: number;
    }> = [];
  
    for (const record of purchaseRecords) {
      const plannedQty = record.plannedQuantity || 0;
      const actualQty = record.actualQuantity || 0;
      const standardPrice = record.standardPrice || 0;
      const actualPrice = record.actualPrice || 0;
  
      // Quantity exceedance: (actual - planned) * standard price
      const qtyExceed = Math.max(0, actualQty - plannedQty) * standardPrice;
      quantityExceedance += qtyExceed;
  
      // Price fluctuation exceedance: (actual price - standard price) * actual quantity
      const priceExceed = Math.max(0, actualPrice - standardPrice) * actualQty;
      priceFluctuationExceedance += priceExceed;
  
      itemizeBreakdown.push({
        itemId: record.itemId,
        itemName: record.itemName,
        category: record.category,
        quantityExceedance: qtyExceed,
        priceFluctuationExceedance: priceExceed,
        totalExceedance: qtyExceed + priceExceed,
      });
    }
  
    // Calculate risk items (sorted by price inflation rate)
    const riskItems: Array<{
      itemId?: string;
      itemName?: string;
      riskLevel: string;
      priceInflationRate: number;
    }> = [];
  
    for (const record of purchaseRecords) {
      const standardPrice = record.standardPrice || 0;
      const actualPrice = record.actualPrice || 0;
  
      if (standardPrice > 0 && actualPrice > standardPrice) {
        const inflationRate = (actualPrice - standardPrice) / standardPrice;
        const riskLevel = inflationRate > 0.2 ? "high" : inflationRate > 0.1 ? "medium" : "low";
  
        if (riskLevel !== "low") {
          riskItems.push({
            itemId: record.itemId,
            itemName: record.itemName,
            riskLevel,
            priceInflationRate: Math.round(inflationRate * 10000) / 10000,
          });
        }
      }
    }
  
    // Sort risk items by inflation rate descending
    riskItems.sort((a, b) => b.priceInflationRate - a.priceInflationRate);
  
    return {
      userId: input.userId,
      yearMonth: input.yearMonth,
      budgetAmount: input.budgetAmount,
      actualSpent: input.actualSpent,
      totalExceedance,
      exceedanceFactors: {
        quantityExceedance: Math.round(quantityExceedance * 100) / 100,
        priceFluctuationExceedance: Math.round(priceFluctuationExceedance * 100) / 100,
      },
      itemizeBreakdown,
      riskItems,
    };
  }
  return { analyzeMonthlyBudgetExceedance };
})();
export const analyzeMonthlyBudgetExceedance: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_31_analyzeMonthlyBudgetExceedance.analyzeMonthlyBudgetExceedance as (...args: any[]) => any)(...args);
