/* AIVIC_FUNCTION_BUNDLE_START owner=adjustMenuPriorityConditions exports=adjustMenuPriorityConditions */
const __aivicBundle_33_adjustMenuPriorityConditions = (() => {
  function adjustMenuPriorityConditions(input: {
    monthlyBudget: number;
    monthlyActual: number;
    currentPriorityConditions: {
      priorityLevel?: number;
      ingredientCategories?: string[];
      nutritionBalanceWeight?: {
        protein?: number;
        carbohydrate?: number;
        fat?: number;
      };
      cookingTimeLimit?: number;
      costPerMeal?: number;
      budgetPriority?: number;
      nutritionPriority?: number;
      targetNutrients?: string[];
      mealGenerationStrategy?: string;
      costReductionTarget?: number;
      restrictedIngredients?: string[];
    };
  }): {
    isAdjusted: boolean;
    nextMonthPriorityConditions: any;
    adjustmentReason: string;
    adjustedBudgetPriority?: number;
    adjustedNutritionPriority?: number;
    adjustedStrategy?: string;
  } {
    const { monthlyBudget, monthlyActual, currentPriorityConditions } = input;
  
    // 予算超過の判定
    const budgetDifference = monthlyActual - monthlyBudget;
    const isOverBudget = budgetDifference > 0;
    const overagePercentage = isOverBudget ? (budgetDifference / monthlyBudget) * 100 : 0;
  
    // 予算内の場合は調整なし
    if (!isOverBudget) {
      return {
        isAdjusted: false,
        nextMonthPriorityConditions: currentPriorityConditions,
        adjustmentReason: '',
      };
    }
  
    // 予算超過時の調整ロジック
    let adjustedBudgetPriority = currentPriorityConditions.budgetPriority ?? 50;
    let adjustedNutritionPriority = currentPriorityConditions.nutritionPriority ?? 50;
    let adjustedStrategy = currentPriorityConditions.mealGenerationStrategy ?? 'balanced_optimization';
    let adjustmentReason = '';
  
    // 超過率に応じた優先度調整
    if (overagePercentage > 20) {
      // 大幅超過：予算重視を強化
      adjustedBudgetPriority = Math.min(100, adjustedBudgetPriority + 15);
      adjustedNutritionPriority = Math.max(0, adjustedNutritionPriority - 10);
      adjustedStrategy = 'low_cost_priority';
      adjustmentReason = `予算超過が大きい（${overagePercentage.toFixed(1)}%）ため予算重視を強化、栄養改善は段階的に実施`;
    } else if (overagePercentage > 10) {
      // 中程度超過：予算優先度を上げる
      adjustedBudgetPriority = Math.min(100, adjustedBudgetPriority + 10);
      adjustedNutritionPriority = Math.max(0, adjustedNutritionPriority - 5);
      adjustedStrategy = 'low_cost_priority';
      adjustmentReason = `予算超過（${overagePercentage.toFixed(1)}%）のため予算重視に調整`;
    } else {
      // 軽微超過：バランス維持
      adjustedBudgetPriority = Math.min(100, adjustedBudgetPriority + 5);
      adjustmentReason = `軽微な予算超過（${overagePercentage.toFixed(1)}%）のため予算配分を微調整`;
    }
  
    const adjustedConditions = {
      ...currentPriorityConditions,
      budgetPriority: adjustedBudgetPriority,
      nutritionPriority: adjustedNutritionPriority,
      mealGenerationStrategy: adjustedStrategy,
    };
  
    return {
      isAdjusted: true,
      nextMonthPriorityConditions: adjustedConditions,
      adjustmentReason,
      adjustedBudgetPriority,
      adjustedNutritionPriority,
      adjustedStrategy,
    };
  }
  return { adjustMenuPriorityConditions };
})();
