/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeMonthlyFoodCostExcessCauses exports=analyzeMonthlyFoodCostExcessCauses */
const __aivicBundle_34_analyzeMonthlyFoodCostExcessCauses = (() => {
  function analyzeMonthlyFoodCostExcessCauses(input: any): any {
    // Validate required input
    if (!input.purchase_records || input.purchase_records.length === 0) {
      throw new Error("購入記録が必要です");
    }
  
    const monthlyBudget = input.monthly_budget ?? input.monthlyBudget ?? 0;
    const actualSpending = input.actual_spending ?? input.actualSpending ?? 0;
    const overageAmount = actualSpending - monthlyBudget;
    const overagePercentage =
      monthlyBudget > 0 ? (overageAmount / monthlyBudget) * 100 : 0;
  
    // If no overage, return empty analysis
    if (overageAmount <= 0) {
      return {
        overageAmount,
        overagePercentage,
        highPriceIngredientImpact: 0,
        unitPriceFluctuationImpact: 0,
        topOverageIngredients: [],
        recommendedAdjustments: [],
      };
    }
  
    // Analyze ingredient costs and price fluctuations
    const ingredientCostMap: Record<
      string,
      {
        totalCost: number;
        quantity: number;
        currentUnitPrice: number;
        priorUnitPrice: number;
        priceFluctuationImpact: number;
      }
    > = {};
  
    const weeklyMenus = input.weeklyMenus ?? [];
    const priorMonthUnitPrices = input.priorMonthUnitPrices ?? {};
    const currentMonthUnitPrices = input.currentMonthUnitPrices ?? {};
  
    // Aggregate ingredient usage and costs
    for (const week of weeklyMenus) {
      const dishes = week.dishes ?? [];
      for (const dish of dishes) {
        const ingredients = dish.ingredients ?? [];
        for (const ingredient of ingredients) {
          const name = ingredient.name ?? "";
          const quantity = ingredient.quantity ?? 0;
          const unitPrice = ingredient.unitPrice ?? 0;
          const currentCost = quantity * unitPrice;
  
          if (!ingredientCostMap[name]) {
            const priorPrice = priorMonthUnitPrices[name] ?? unitPrice;
            const currentPrice = currentMonthUnitPrices[name] ?? unitPrice;
            const priceFluctuation = (currentPrice - priorPrice) * quantity;
  
            ingredientCostMap[name] = {
              totalCost: currentCost,
              quantity,
              currentUnitPrice: currentPrice,
              priorUnitPrice: priorPrice,
              priceFluctuationImpact: Math.max(0, priceFluctuation),
            };
          } else {
            ingredientCostMap[name].totalCost += currentCost;
            ingredientCostMap[name].quantity += quantity;
            const priceFluctuation =
              (ingredientCostMap[name].currentUnitPrice -
                ingredientCostMap[name].priorUnitPrice) *
              ingredientCostMap[name].quantity;
            ingredientCostMap[name].priceFluctuationImpact = Math.max(
              0,
              priceFluctuation
            );
          }
        }
      }
    }
  
    // Calculate impacts
    let totalHighPriceImpact = 0;
    let totalPriceFluctuationImpact = 0;
  
    const ingredientImpacts: Array<{
      name: string;
      highPriceImpact: number;
      priceFluctuationImpact: number;
      totalImpact: number;
    }> = [];
  
    for (const [name, data] of Object.entries(ingredientCostMap)) {
      const priorCost = data.quantity * data.priorUnitPrice;
      const currentCost = data.totalCost;
      const highPriceImpact = Math.max(0, currentCost - priorCost);
  
      ingredientImpacts.push({
        name,
        highPriceImpact,
        priceFluctuationImpact: data.priceFluctuationImpact,
        totalImpact: highPriceImpact + data.priceFluctuationImpact,
      });
  
      totalHighPriceImpact += highPriceImpact;
      totalPriceFluctuationImpact += data.priceFluctuationImpact;
    }
  
    // Sort by total impact and get top 3
    ingredientImpacts.sort((a, b) => b.totalImpact - a.totalImpact);
    const topOverageIngredients = ingredientImpacts.slice(0, 3).map((item) => ({
      ingredientName: item.name,
      overageContribution: item.totalImpact,
      reason:
        item.highPriceImpact > item.priceFluctuationImpact
          ? "高価食材の使用増加"
          : "単価変動による影響",
    }));
  
    // Generate recommendations
    const recommendedAdjustments: Array<{
      category: string;
      suggestion: string;
      expectedSavings: number;
    }> = [];
  
    if (totalHighPriceImpact > 0) {
      recommendedAdjustments.push({
        category: "高価食材",
        suggestion: `${topOverageIngredients[0]?.ingredientName ?? "高価食材"}の使用を月1回以下に制限`,
        expectedSavings: Math.min(
          totalHighPriceImpact,
          overageAmount * 0.75
        ),
      });
    }
  
    if (totalPriceFluctuationImpact > 0) {
      recommendedAdjustments.push({
        category: "単価変動",
        suggestion: "季節商品の購入時期を調整し、単価が安定した時期に購入",
        expectedSavings: Math.min(
          totalPriceFluctuationImpact,
          overageAmount * 0.25
        ),
      });
    }
  
    return {
      overageAmount,
      overagePercentage,
      highPriceIngredientImpact: totalHighPriceImpact,
      unitPriceFluctuationImpact: totalPriceFluctuationImpact,
      topOverageIngredients,
      recommendedAdjustments,
    };
  }
  return { analyzeMonthlyFoodCostExcessCauses };
})();
export const analyzeMonthlyFoodCostExcessCauses = __aivicBundle_34_analyzeMonthlyFoodCostExcessCauses.analyzeMonthlyFoodCostExcessCauses;
/* AIVIC_FUNCTION_BUNDLE_END owner=analyzeMonthlyFoodCostExcessCauses */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMonthlyBudgetExcessFactor exports=calculateMonthlyBudgetExcessFactor */
const __aivicBundle_35_calculateMonthlyBudgetExcessFactor = (() => {
  interface CalculateMonthlyBudgetExcessFactorInput {
    user_id: string;
    monthly_budget: number;
    current_month_total_cost: number;
    purchases: Array<{
      ingredient_name: string;
      unit_price: number;
      quantity: number;
      category: string;
    }>;
    analysis_date: Date;
  }
  
  interface CalculateMonthlyBudgetExcessFactorResult {
    excess_amount: number;
    excess_ratio: number;
    exceeds_50_percent_threshold: boolean;
    category_breakdown: {
      meat_cost: number;
      fish_cost: number;
      vegetable_cost: number;
      grain_cost: number;
    };
    next_month_priority_mode: string;
    target_cost_reduction_ratio: number;
  }
  
   function calculateMonthlyBudgetExcessFactor(
    input: CalculateMonthlyBudgetExcessFactorInput
  ): CalculateMonthlyBudgetExcessFactorResult {
    // Validate required inputs
    if (!String(input.user_id).trim()) {
      throw new Error("user_id is required");
    }
    if (!input.analysis_date) {
      throw new Error("analysis_date is required");
    }
  
    const {
      monthly_budget,
      current_month_total_cost,
      purchases,
    } = input;
  
    // Calculate excess amount and ratio
    const excess_amount = current_month_total_cost - monthly_budget;
    const excess_ratio = excess_amount / monthly_budget;
  
    // Determine if excess exceeds 50% threshold
    const exceeds_50_percent_threshold = excess_ratio >= 0.5;
  
    // Calculate category breakdown
    const category_breakdown = {
      meat_cost: 0,
      fish_cost: 0,
      vegetable_cost: 0,
      grain_cost: 0,
    };
  
    for (const purchase of purchases) {
      const item_cost = purchase.unit_price * purchase.quantity;
      const category = purchase.category.toLowerCase();
  
      if (category === 'meat') {
        category_breakdown.meat_cost += item_cost;
      } else if (category === 'fish') {
        category_breakdown.fish_cost += item_cost;
      } else if (category === 'vegetable') {
        category_breakdown.vegetable_cost += item_cost;
      } else if (category === 'grain') {
        category_breakdown.grain_cost += item_cost;
      }
    }
  
    // Determine next month priority mode and cost reduction target based on excess threshold
    let next_month_priority_mode = 'balanced';
    let target_cost_reduction_ratio = 0;
  
    if (exceeds_50_percent_threshold) {
      next_month_priority_mode = 'low_price_priority';
      target_cost_reduction_ratio = 0.15; // 15% reduction target
    }
  
    return {
      excess_amount,
      excess_ratio,
      exceeds_50_percent_threshold,
      category_breakdown,
      next_month_priority_mode,
      target_cost_reduction_ratio,
    };
  }
  return { calculateMonthlyBudgetExcessFactor };
})();
export const calculateMonthlyBudgetExcessFactor = __aivicBundle_35_calculateMonthlyBudgetExcessFactor.calculateMonthlyBudgetExcessFactor;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateMonthlyBudgetExcessFactor */

