const __aivicBundle_41_calculateMenuScores = (() => {
  interface CalculateMenuScoresInput {
    menuProposals: Array<{
      id: string;
      name: string;
      ingredients: Array<{
        id: string;
        name: string;
        isInSeason: boolean;
        quantity: number;
      }>;
    }>;
    seasonalData: Record<
      string,
      {
        inSeasonScore: number;
        basePriceJpy: number;
      }
    >;
    discountData: Array<{
      id: string;
      discountRatePercent: number;
      retailerId: string;
    }>;
    inventoryData: Array<{
      id: string;
      stockLevel: number;
      retailerId: string;
      capacityThroughput: number;
    }>;
  }
  
  interface ScoredMenu {
    menuId: string;
    totalScore: number;
    seasonalScore: number;
    discountScore: number;
    inventoryFulfillmentScore: number;
    breakdown: {
      seasonalComponent: number;
      discountComponent: number;
      inventoryComponent: number;
      baseScore: number;
    };
  }
  
   function calculateMenuScores(
    input: CalculateMenuScoresInput
  ): ScoredMenu[] {
    const { menuProposals, seasonalData, discountData, inventoryData } = input;
  
    const discountMap = new Map<string, number>();
    discountData.forEach((discount) => {
      discountMap.set(discount.id, discount.discountRatePercent);
    });
  
    const inventoryMap = new Map<
      string,
      { stockLevel: number; capacityThroughput: number }
    >();
    inventoryData.forEach((inv) => {
      inventoryMap.set(inv.id, {
        stockLevel: inv.stockLevel,
        capacityThroughput: inv.capacityThroughput,
      });
    });
  
    const scoredMenus: ScoredMenu[] = menuProposals.map((menu) => {
      let totalSeasonalScore = 0;
      let totalDiscountScore = 0;
      let totalInventoryFulfillment = 0;
      const ingredientCount = menu.ingredients.length;
  
      menu.ingredients.forEach((ingredient) => {
        const seasonal = seasonalData[ingredient.id];
        if (seasonal) {
          totalSeasonalScore += seasonal.inSeasonScore;
        }
  
        const discount = discountMap.get(ingredient.id);
        if (discount) {
          totalDiscountScore += discount;
        }
  
        const inventory = inventoryMap.get(ingredient.id);
        if (inventory) {
          const fulfillmentRatio =
            inventory.stockLevel / inventory.capacityThroughput;
          totalInventoryFulfillment += fulfillmentRatio;
        }
      });
  
      const avgSeasonalScore =
        ingredientCount > 0 ? totalSeasonalScore / ingredientCount : 0;
      const seasonalComponent = avgSeasonalScore * 20;
  
      const avgDiscountScore =
        ingredientCount > 0 ? totalDiscountScore / ingredientCount : 0;
      const discountComponent = avgDiscountScore * 15;
  
      const avgInventoryFulfillment =
        ingredientCount > 0 ? totalInventoryFulfillment / ingredientCount : 0;
      const inventoryFulfillmentScore = avgInventoryFulfillment * 100;
  
      const baseScore = 100;
      const totalScore =
        seasonalComponent + discountComponent + inventoryFulfillmentScore + baseScore;
  
      return {
        menuId: menu.id,
        totalScore,
        seasonalScore: seasonalComponent,
        discountScore: discountComponent,
        inventoryFulfillmentScore,
        breakdown: {
          seasonalComponent,
          discountComponent,
          inventoryComponent: inventoryFulfillmentScore,
          baseScore,
        },
      };
    });
  
    scoredMenus.sort((a, b) => b.totalScore - a.totalScore);
  
    return scoredMenus;
  }
  return { calculateMenuScores };
})();
export const calculateMenuScores = __aivicBundle_41_calculateMenuScores.calculateMenuScores;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateMenuScores */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMealPlanScores exports=calculateMealPlanScores */
const __aivicBundle_42_calculateMealPlanScores = (() => {
  function calculateMealPlanScores(
    mealPlans: Array<{
      id?: string;
      name?: string;
      dishes?: string[];
      ingredients?: Array<{ name: string; quantity: number; unit: string }>;
      nutritionBalance?: number;
    }>,
    distributorData: {
      [ingredientName: string]: {
        inStock: boolean;
        stockLevel: number;
        price: number;
        seasonalDiscount: number;
      };
    }
  ): Array<{
    id?: string;
    totalScore: number;
    stockFulfillmentScore: number;
    priceScore: number;
    nutritionBalanceScore: number;
  }> {
    return mealPlans.map((mealPlan) => {
      const ingredients = mealPlan.ingredients || [];
  
      // Calculate stock fulfillment score (0-100)
      let stockFulfillmentScore = 0;
      if (ingredients.length > 0) {
        const stockLevels = ingredients
          .map((ing) => {
            const distributorInfo = distributorData[ing.name];
            return distributorInfo ? distributorInfo.stockLevel : 0;
          })
          .filter((level) => level > 0);
  
        if (stockLevels.length > 0) {
          stockFulfillmentScore =
            stockLevels.reduce((sum, level) => sum + level, 0) / stockLevels.length;
        }
      }
  
      // Calculate price score (0-100)
      let priceScore = 0;
      if (ingredients.length > 0) {
        const priceData = ingredients
          .map((ing) => {
            const distributorInfo = distributorData[ing.name];
            if (!distributorInfo) return null;
            const discountRate = distributorInfo.seasonalDiscount;
            return discountRate;
          })
          .filter((discount) => discount !== null);
  
        if (priceData.length > 0) {
          const avgDiscount =
            priceData.reduce((sum, discount) => sum + discount, 0) / priceData.length;
          priceScore = 100 - avgDiscount * 0.5;
        }
      }
  
      // Use nutrition balance score from input
      const nutritionBalanceScore = mealPlan.nutritionBalance || 0;
  
      // Calculate total score with weights: stock 0.3, price 0.3, nutrition 0.4
      const totalScore =
        stockFulfillmentScore * 0.3 +
        priceScore * 0.3 +
        nutritionBalanceScore * 0.4;
  
      return {
        id: mealPlan.id,
        totalScore: Math.round(totalScore * 100) / 100,
        stockFulfillmentScore: Math.round(stockFulfillmentScore * 100) / 100,
        priceScore: Math.round(priceScore * 100) / 100,
        nutritionBalanceScore,
      };
    });
  }
  return { calculateMealPlanScores };
})();
export const calculateMealPlanScores = __aivicBundle_42_calculateMealPlanScores.calculateMealPlanScores;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateMealPlanScores */

/* AIVIC_FUNCTION_BUNDLE_START owner=selectBestMealPlan exports=selectBestMealPlan */
const __aivicBundle_43_selectBestMealPlan = (() => {
  function selectBestMealPlan(
    mealPlanCandidates: Array<{
      id?: string;
      mealPlanId?: string;
      overallScore?: number;
      totalScore?: number;
      constraintViolations?: Array<string>;
      familySatisfactionScore?: number;
      stockFulfillmentScore?: number;
      priceScore?: number;
      nutritionBalanceScore?: number;
    }>
  ): {
    id?: string;
    selectedMealPlanId?: string;
    selectionReason: string;
    alternativePlans: Array<{ mealPlanId?: string; id?: string; score: number }>;
    totalScore?: number;
    stockFulfillmentScore?: number;
    priceScore?: number;
    nutritionBalanceScore?: number;
  } {
    if (!mealPlanCandidates || mealPlanCandidates.length === 0) {
      return {
        selectionReason: "候補がありません",
        alternativePlans: [],
      };
    }
  
    const candidates = mealPlanCandidates.map((plan) => ({
      id: plan.id || plan.mealPlanId,
      score: plan.totalScore ?? plan.overallScore ?? 0,
      violationCount: plan.constraintViolations?.length ?? 0,
      familySatisfactionScore: plan.familySatisfactionScore ?? 0,
      stockFulfillmentScore: plan.stockFulfillmentScore,
      priceScore: plan.priceScore,
      nutritionBalanceScore: plan.nutritionBalanceScore,
      originalPlan: plan,
    }));
  
    let bestCandidate = candidates[0];
    let selectionReason = "";
  
    const candidatesWithoutViolations = candidates.filter(
      (c) => c.violationCount === 0
    );
  
    if (candidatesWithoutViolations.length > 0) {
      bestCandidate = candidatesWithoutViolations.reduce((prev, current) =>
        current.score > prev.score ? current : prev
      );
      selectionReason = "最高スコア・制約違反なし";
    } else {
      const minViolations = Math.min(...candidates.map((c) => c.violationCount));
      const candidatesWithMinViolations = candidates.filter(
        (c) => c.violationCount === minViolations
      );
      bestCandidate = candidatesWithMinViolations.reduce((prev, current) =>
        current.score > prev.score ? current : prev
      );
      selectionReason = "違反数最小";
    }
  
    const alternativePlans = candidates
      .filter((c) => c.id !== bestCandidate.id)
      .sort((a, b) => b.score - a.score)
      .map((c) => ({
        mealPlanId: c.id,
        id: c.id,
        score: c.score,
      }));
  
    const result: any = {
      id: bestCandidate.id,
      selectedMealPlanId: bestCandidate.id,
      selectionReason,
      alternativePlans,
      totalScore: bestCandidate.score,
    };
  
    if (bestCandidate.stockFulfillmentScore !== undefined) {
      result.stockFulfillmentScore = bestCandidate.stockFulfillmentScore;
    }
    if (bestCandidate.priceScore !== undefined) {
      result.priceScore = bestCandidate.priceScore;
    }
    if (bestCandidate.nutritionBalanceScore !== undefined) {
      result.nutritionBalanceScore = bestCandidate.nutritionBalanceScore;
    }
  
    return result;
  }
  return { selectBestMealPlan };
})();
export const selectBestMealPlan = __aivicBundle_43_selectBestMealPlan.selectBestMealPlan;
/* AIVIC_FUNCTION_BUNDLE_END owner=selectBestMealPlan */

