const __aivicBundle_44_calculateMenuScoringWithInventory = (() => {
  function calculateMenuScoringWithInventory(
    menuProposal: {
      menu_id: string;
      name: string;
      ingredients: Array<{
        ingredient_id: string;
        name: string;
        quantity: number;
        unit: string;
        distributor_id: string;
        inventory_status: number;
        unit_price: number;
        is_seasonal: boolean;
        is_discounted: boolean;
      }>;
      nutrition_scores: {
        protein_achievement: number;
        carbohydrate_achievement: number;
        fat_achievement: number;
        vitamin_achievement: number;
      };
      cooking_time_minutes: number;
      family_preference_score: number;
      budget_constraint_satisfaction: number;
    },
    scoringParams: {
      nutrition_weight: number;
      inventory_availability_weight: number;
      seasonal_discount_weight: number;
      budget_satisfaction_weight: number;
      cooking_time_normalization: number;
      zero_inventory_penalty_factor: number;
    }
  ): {
    menu_id: string;
    inventory_availability_score: number;
    overall_score: number;
  } {
    if (!String(menuProposal.name).trim()) {
      throw new Error("name is required");
    }
    if (menuProposal.cooking_time_minutes === undefined || menuProposal.cooking_time_minutes === null) {
      throw new Error("cooking_time_minutes is required");
    }
    if (menuProposal.family_preference_score === undefined || menuProposal.family_preference_score === null) {
      throw new Error("family_preference_score is required");
    }
    if (scoringParams.cooking_time_normalization === undefined || scoringParams.cooking_time_normalization === null) {
      throw new Error("cooking_time_normalization is required");
    }
    if (scoringParams.zero_inventory_penalty_factor === undefined || scoringParams.zero_inventory_penalty_factor === null) {
      throw new Error("zero_inventory_penalty_factor is required");
    }
  
    const menuId = menuProposal.menu_id;
  
    // Calculate inventory availability score
    const totalIngredients = menuProposal.ingredients.length;
    let availableIngredientsCount = 0;
  
    for (const ingredient of menuProposal.ingredients) {
      if (ingredient.inventory_status > 0) {
        availableIngredientsCount += 1;
      }
    }
  
    const inventoryAvailabilityScore =
      totalIngredients > 0 ? availableIngredientsCount / totalIngredients : 0;
  
    // Calculate nutrition score (average of all nutrition achievements)
    const nutritionScore =
      (menuProposal.nutrition_scores.protein_achievement +
        menuProposal.nutrition_scores.carbohydrate_achievement +
        menuProposal.nutrition_scores.fat_achievement +
        menuProposal.nutrition_scores.vitamin_achievement) /
      4;
  
    // Calculate seasonal discount score
    let seasonalDiscountScore = 0;
    let seasonalIngredientCount = 0;
    for (const ingredient of menuProposal.ingredients) {
      if (ingredient.is_seasonal) {
        seasonalIngredientCount += 1;
        if (ingredient.is_discounted) {
          seasonalDiscountScore += 1;
        }
      }
    }
    const seasonalDiscountRatio =
      seasonalIngredientCount > 0
        ? seasonalDiscountScore / seasonalIngredientCount
        : 0;
  
    // Calculate budget score
    const budgetScore = menuProposal.budget_constraint_satisfaction;
  
    // Calculate cooking time score (normalized to 0-1)
    const cookingTimeScore = Math.min(
      1,
      scoringParams.cooking_time_normalization / menuProposal.cooking_time_minutes
    );
  
    // Apply zero inventory penalty factor based on family preference score
    const zeroInventoryPenalty = scoringParams.zero_inventory_penalty_factor * (1 - inventoryAvailabilityScore);
    const adjustedInventoryScore = Math.max(0, inventoryAvailabilityScore - zeroInventoryPenalty);
  
    // Calculate overall score using weighted formula
    const overallScore =
      nutritionScore * scoringParams.nutrition_weight +
      adjustedInventoryScore * scoringParams.inventory_availability_weight * 100 +
      seasonalDiscountRatio * scoringParams.seasonal_discount_weight * 100 +
      budgetScore * scoringParams.budget_satisfaction_weight * 100 +
      cookingTimeScore * 5 +
      menuProposal.family_preference_score * 2;
  
    return {
      menu_id: menuId,
      inventory_availability_score: inventoryAvailabilityScore,
      overall_score: overallScore,
    };
  }
  return { calculateMenuScoringWithInventory };
})();
export const calculateMenuScoringWithInventory = __aivicBundle_44_calculateMenuScoringWithInventory.calculateMenuScoringWithInventory;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateMenuScoringWithInventory */

