const __aivicBundle_46_calculateDeviationRate = (() => {
  interface CalculateDeviationRateInput {
    predicted_demand: number;
    actual_demand: number;
  }
  
   function calculateDeviationRate(
    input: CalculateDeviationRateInput
  ): number {
    const { predicted_demand, actual_demand } = input;
  
    if (predicted_demand <= 0) {
      throw new Error('予測値は正の数である必要があります');
    }
  
    if (actual_demand < 0) {
      throw new Error('実績値は非負の数である必要があります');
    }
  
    const deviationRate = actual_demand - predicted_demand;
  
    return deviationRate;
  }
  return { calculateDeviationRate };
})();
