const __aivicBundle_47_generateImprovement = (() => {
  interface GenerateImprovementInput {
    deviation_rate: number;
    deviation_category: string;
    prediction_model_version: string;
  }
  
  interface GenerateImprovementOutput {
    should_improve: boolean;
    priority: 'high' | 'medium' | null;
    recommendation: string | null;
  }
  
   function generateImprovement(
    input: GenerateImprovementInput
  ): GenerateImprovementOutput {
    if (input.deviation_rate === null || input.deviation_rate === undefined) {
      throw new Error('乖離度が指定されていません');
    }
  
    if (typeof input.deviation_rate !== 'number') {
      throw new Error('乖離度は数値である必要があります');
    }
  
    const validCategories = ['低乖離', '中乖離', '高乖離'];
    if (!validCategories.includes(input.deviation_category)) {
      throw new Error('無効なカテゴリが指定されています');
    }
  
    if (!input.prediction_model_version || input.prediction_model_version === '') {
      throw new Error('モデルバージョンが指定されていません');
    }
  
    const deviationRate = input.deviation_rate;
  
    if (deviationRate <= 5) {
      return {
        should_improve: false,
        priority: null,
        recommendation: null,
      };
    }
  
    if (deviationRate > 5 && deviationRate < 15) {
      return {
        should_improve: true,
        priority: 'medium',
        recommendation: '予測モデルのパラメータ調整を検討してください',
      };
    }
  
    if (deviationRate >= 15) {
      return {
        should_improve: true,
        priority: 'high',
        recommendation: '予測モデルの再学習が必要です',
      };
    }
  
    return {
      should_improve: false,
      priority: null,
      recommendation: null,
    };
  }
  return { generateImprovement };
})();
