/* AIVIC_FUNCTION_BUNDLE_START owner=getWeeklyNutritionDashboard exports=getWeeklyNutritionDashboard */
const __aivicBundle_57_getWeeklyNutritionDashboard = (() => {
  function getWeeklyNutritionDashboard(input: {
    userId: string;
    weekStartDate: string;
    weekEndDate?: string;
    mealRecords?: Array<{
      userId?: string;
      mealDate: string;
      mealType?: string;
      nutritionItems: Array<{
        nutrientId: string;
        actualValue: number;
        unit: string;
      }>;
    }>;
    nutritionTargets?: Array<{
      nutrientId: string;
      targetValue: number;
      unit: string;
    }>;
  }): {
    weekStartDate: string;
    weekEndDate?: string;
    nutritionSummary: Array<{
      nutrientId: string;
      totalActualValue: number;
      targetValue: number;
      achievementRate: number;
      unit: string;
      gap: number;
    }>;
  } {
    const {
      userId,
      weekStartDate,
      weekEndDate,
      mealRecords = [],
      nutritionTargets = [],
    } = input;
  
    if (!nutritionTargets || nutritionTargets.length === 0) {
      throw new Error("栄養目標が設定されていません");
    }
  
    const userMealRecords = mealRecords.filter(
      (record) => !record.userId || record.userId === userId
    );
  
    if (userMealRecords.length === 0) {
      throw new Error(`当週のデータが見つかりません: ユーザー ${userId}`);
    }
  
    const nutritionMap: Record<
      string,
      { totalActual: number; target: number; unit: string }
    > = {};
  
    for (const target of nutritionTargets) {
      nutritionMap[target.nutrientId] = {
        totalActual: 0,
        target: target.targetValue,
        unit: target.unit,
      };
    }
  
    for (const record of userMealRecords) {
      for (const item of record.nutritionItems) {
        if (nutritionMap[item.nutrientId]) {
          nutritionMap[item.nutrientId].totalActual += item.actualValue;
        }
      }
    }
  
    const nutritionSummary = Object.entries(nutritionMap).map(
      ([nutrientId, data]) => {
        const achievementRate = (data.totalActual / data.target) * 100;
        const gap = data.totalActual - data.target;
  
        return {
          nutrientId,
          totalActualValue: data.totalActual,
          targetValue: data.target,
          achievementRate: Math.round(achievementRate * 100) / 100,
          unit: data.unit,
          gap,
        };
      }
    );
  
    return {
      weekStartDate,
      weekEndDate,
      nutritionSummary,
    };
  }
  return { getWeeklyNutritionDashboard };
})();
export const getWeeklyNutritionDashboard = __aivicBundle_57_getWeeklyNutritionDashboard.getWeeklyNutritionDashboard;
