/* AIVIC_FUNCTION_BUNDLE_START owner=calculateWeeklyDashboardMetrics exports=calculateWeeklyDashboardMetrics */
const __aivicBundle_58_calculateWeeklyDashboardMetrics = (() => {
  function calculateWeeklyDashboardMetrics(input: {
    userId: string;
    weekStartDate: Date;
    weekEndDate: Date;
    foodRecords: Array<{
      recordId?: string;
      userId?: string;
      recordDate?: Date;
      nutrientIntake?: Record<string, number>;
      date?: string;
      nutritionData?: Record<string, number>;
      satisfactionScore?: number;
    }>;
    nutritionTargets: Record<string, number>;
    userRegistrationDate: Date;
  }): {
    userId: string;
    weekStartDate: Date;
    weeklyAggregates: Record<string, number>;
    achievementScores: Record<string, number>;
    priorWeekComparison: null | Record<string, number>;
    isFirstWeek: boolean;
    improvementGaps: Array<{
      nutrient: string;
      targetValue: number;
      actualValue: number;
      gapValue: number;
      gapPercentage: number;
      priority: number;
    }>;
    dashboardDisplay: {
      weekLabel: string;
      priorWeekComparisonLabel: string;
      isInitialWeek: boolean;
    };
    errorOccurred: boolean;
    errorMessage: null | string;
  } {
    const {
      userId,
      weekStartDate,
      weekEndDate,
      foodRecords,
      nutritionTargets,
      userRegistrationDate,
    } = input;
  
    // Determine if this is the first week (week starts within 7 days of registration)
    const weekStartTime = weekStartDate.getTime();
    const registrationTime = userRegistrationDate.getTime();
    const daysSinceRegistration = (weekStartTime - registrationTime) / (1000 * 60 * 60 * 24);
    const isFirstWeek = daysSinceRegistration >= 0 && daysSinceRegistration < 7;
  
    // Extract nutrition data from records
    const nutrientKeys = Object.keys(nutritionTargets);
    const weeklyAggregates: Record<string, number> = {};
    const nutrientSums: Record<string, number> = {};
  
    // Initialize sums
    nutrientKeys.forEach((key) => {
      nutrientSums[key] = 0;
    });
  
    // Accumulate nutrition data from records
    foodRecords.forEach((record) => {
      const nutrients = record.nutrientIntake || record.nutritionData || {};
      nutrientKeys.forEach((key) => {
        if (key in nutrients) {
          nutrientSums[key] += nutrients[key];
        }
      });
    });
  
    // Calculate averages
    const recordCount = foodRecords.length || 1;
    nutrientKeys.forEach((key) => {
      const avgKey = `avg${key.charAt(0).toUpperCase()}${key.slice(1)}`;
      weeklyAggregates[avgKey] = Math.round(nutrientSums[key] / recordCount);
    });
  
    // Calculate achievement scores (as percentages, rounded)
    const achievementScores: Record<string, number> = {};
    nutrientKeys.forEach((key) => {
      const avgKey = `avg${key.charAt(0).toUpperCase()}${key.slice(1)}`;
      const avgValue = weeklyAggregates[avgKey];
      const targetValue = nutritionTargets[key];
      const achievementRate = Math.round((avgValue / targetValue) * 100);
      const scoreKey = `${key}AchievementRate`;
      achievementScores[scoreKey] = achievementRate;
    });
  
    // Calculate improvement gaps and prioritize by deficit (lowest achievement first)
    const improvementGapsUnsorted = nutrientKeys.map((key) => {
      const avgKey = `avg${key.charAt(0).toUpperCase()}${key.slice(1)}`;
      const actualValue = weeklyAggregates[avgKey];
      const targetValue = nutritionTargets[key];
      const gapValue = actualValue - targetValue;
      const gapPercentage = Math.round((gapValue / targetValue) * 100);
  
      return {
        nutrient: key,
        targetValue,
        actualValue,
        gapValue,
        gapPercentage,
        achievementRate: Math.round((actualValue / targetValue) * 100),
      };
    });
  
    // Sort by achievement rate (ascending) to prioritize deficiencies
    const improvementGaps = improvementGapsUnsorted
      .sort((a, b) => a.achievementRate - b.achievementRate)
      .map((gap, index) => ({
        nutrient: gap.nutrient,
        targetValue: gap.targetValue,
        actualValue: gap.actualValue,
        gapValue: gap.gapValue,
        gapPercentage: gap.gapPercentage,
        priority: index + 1,
      }));
  
    // Format week label
    const weekStart = new Date(weekStartDate);
    const weekEnd = new Date(weekEndDate);
    const monthStart = weekStart.toLocaleString('en-US', { month: 'short' });
    const dayStart = weekStart.getDate();
    const dayEnd = weekEnd.getDate();
    const yearStart = weekStart.getFullYear();
    const weekLabel = `Week of ${monthStart} ${dayStart} - ${monthStart} ${dayEnd}, ${yearStart}`;
  
    // Dashboard display
    const dashboardDisplay = {
      weekLabel,
      priorWeekComparisonLabel: isFirstWeek ? 'N/A' : 'Prior Week Comparison',
      isInitialWeek: isFirstWeek,
    };
  
    return {
      userId,
      weekStartDate,
      weeklyAggregates,
      achievementScores,
      priorWeekComparison: isFirstWeek ? null : {},
      isFirstWeek,
      improvementGaps,
      dashboardDisplay,
      errorOccurred: false,
      errorMessage: null,
    };
  }
  return { calculateWeeklyDashboardMetrics };
})();
export const calculateWeeklyDashboardMetrics = __aivicBundle_58_calculateWeeklyDashboardMetrics.calculateWeeklyDashboardMetrics;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateWeeklyDashboardMetrics */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateSegmentEffectiveMetrics exports=calculateSegmentEffectiveMetrics */
const __aivicBundle_59_calculateSegmentEffectiveMetrics = (() => {
  function calculateSegmentEffectiveMetrics(input: {
    segment_type: string;
    analysis_start_date: Date;
    analysis_end_date: Date;
    menu_generation_requests: Array<{
      request_id: string;
      status: string;
      generated_at: Date;
    }>;
    cooking_time_records: Array<{
      request_id: string;
      standard_cooking_minutes: number;
      actual_cooking_minutes: number;
    }>;
    satisfaction_ratings: Array<{
      request_id: string;
      satisfaction_score: number;
    }>;
  }): {
    segment_type: string;
    analysis_start_date: Date;
    analysis_end_date: Date;
    success_rate: number;
    cooking_time_reduction_degree: number;
    satisfaction_score: number;
  } {
    const {
      segment_type,
      analysis_start_date,
      analysis_end_date,
      menu_generation_requests,
      cooking_time_records,
      satisfaction_ratings,
    } = input;
  
    // 献立生成成功率の計算
    const total_requests = menu_generation_requests.length;
    const successful_requests = menu_generation_requests.filter(
      (req) => req.status === 'success'
    ).length;
    const success_rate =
      total_requests > 0
        ? Math.round((successful_requests / total_requests) * 100)
        : 0;
  
    // 調理時間短縮度の計算
    let total_reduction_percentage = 0;
    if (cooking_time_records.length > 0) {
      total_reduction_percentage = cooking_time_records.reduce((sum, record) => {
        const reduction_percentage =
          ((record.standard_cooking_minutes - record.actual_cooking_minutes) /
            record.standard_cooking_minutes) *
          100;
        return sum + reduction_percentage;
      }, 0);
    }
    const cooking_time_reduction_degree =
      cooking_time_records.length > 0
        ? total_reduction_percentage / cooking_time_records.length
        : 0;
  
    // 満足度スコアの計算（平均値）
    let total_satisfaction = 0;
    if (satisfaction_ratings.length > 0) {
      total_satisfaction = satisfaction_ratings.reduce(
        (sum, rating) => sum + rating.satisfaction_score,
        0
      );
    }
    const satisfaction_score =
      satisfaction_ratings.length > 0
        ? total_satisfaction / satisfaction_ratings.length
        : 0;
  
    return {
      segment_type,
      analysis_start_date,
      analysis_end_date,
      success_rate,
      cooking_time_reduction_degree,
      satisfaction_score,
    };
  }
  return { calculateSegmentEffectiveMetrics };
})();
export const calculateSegmentEffectiveMetrics = __aivicBundle_59_calculateSegmentEffectiveMetrics.calculateSegmentEffectiveMetrics;
