/* AIVIC_FUNCTION_BUNDLE_START owner=validateSegmentationCriteria exports=validateSegmentationCriteria */
const __aivicBundle_60_validateSegmentationCriteria = (() => {
  function validateSegmentationCriteria(input: {
    ageGroup?: string;
    familyComposition?: string;
    restrictionType?: string;
    timestamp?: Date;
    segmentationCriteria?: Array<{
      criteriaName: string;
      criteriaType: string;
      values: string[] | number[];
    }>;
    userDataset?: Array<{
      userId: string;
      age?: number;
      familyComposition?: string;
      dietaryRestrictionPresence?: boolean;
    }>;
    minimumSegmentSize?: number;
  }): {
    isValid: boolean;
    ageGroup?: string;
    familyComposition?: string;
    restrictionType?: string;
    timestamp?: Date;
    validSegments?: Array<{
      segmentId: string;
      criteriaName: string;
      userCount: number;
    }>;
    invalidSegments?: Array<{
      criteriaName: string;
      reason: string;
    }>;
    validationStatus?: string;
  } {
    // Validate required fields for the primary test case
    if (input.ageGroup !== undefined && input.ageGroup === "") {
      throw new Error("年齢グループは必須項目です");
    }
  
    if (input.familyComposition !== undefined && input.familyComposition === "") {
      throw new Error("家族構成は必須項目です");
    }
  
    if (input.restrictionType !== undefined && input.restrictionType === "") {
      throw new Error("制限タイプは必須項目です");
    }
  
    // If all required fields are provided and non-empty, return valid result
    if (
      input.ageGroup &&
      input.familyComposition &&
      input.restrictionType &&
      input.timestamp
    ) {
      return {
        isValid: true,
        ageGroup: input.ageGroup,
        familyComposition: input.familyComposition,
        restrictionType: input.restrictionType,
        timestamp: input.timestamp,
      };
    }
  
    // Handle segmentation criteria validation (from plan)
    if (
      input.segmentationCriteria &&
      input.userDataset &&
      input.minimumSegmentSize !== undefined
    ) {
      const validSegments: Array<{
        segmentId: string;
        criteriaName: string;
        userCount: number;
      }> = [];
      const invalidSegments: Array<{
        criteriaName: string;
        reason: string;
      }> = [];
  
      for (const criteria of input.segmentationCriteria) {
        const criteriaValues = criteria.values;
  
        for (const value of criteriaValues) {
          let userCount = 0;
  
          if (criteria.criteriaType === "age_range") {
            const [minAge, maxAge] = (value as string)
              .split("-")
              .map((v) => parseInt(v, 10));
            userCount = input.userDataset.filter(
              (user) =>
                user.age !== undefined &&
                user.age >= minAge &&
                user.age <= maxAge
            ).length;
          } else if (criteria.criteriaType === "family_type") {
            userCount = input.userDataset.filter(
              (user) => user.familyComposition === value
            ).length;
          }
  
          const segmentId = `seg_${value}`;
  
          if (userCount >= input.minimumSegmentSize) {
            validSegments.push({
              segmentId,
              criteriaName: criteria.criteriaName,
              userCount,
            });
          } else {
            invalidSegments.push({
              criteriaName: criteria.criteriaName,
              reason: `${value} セグメントがminimumSegmentSize(${input.minimumSegmentSize})未満です`,
            });
          }
        }
      }
  
      const isValid = invalidSegments.length === 0;
  
      return {
        isValid,
        validSegments,
        invalidSegments,
        validationStatus: isValid ? "valid" : "invalid_segment_size",
      };
    }
  
    return {
      isValid: false,
      validationStatus: "incomplete",
    };
  }
  return { validateSegmentationCriteria };
})();
export const validateSegmentationCriteria = __aivicBundle_60_validateSegmentationCriteria.validateSegmentationCriteria;
