/* AIVIC_FUNCTION_BUNDLE_START owner=calculateSegmentStatistics exports=calculateSegmentStatistics */
const __aivicBundle_61_calculateSegmentStatistics = (() => {
  interface CalculateSegmentStatisticsInput {
    segmentId: string;
    segmentName: string;
    users: Array<{
      userId: string;
      satisfactionScore?: number;
      cookingTimeReduction?: number;
      nutritionAchievementRate?: number;
    }>;
  }
  
  interface CalculateSegmentStatisticsResult {
    segmentId: string;
    segmentName: string;
    userCount: number;
    averageSatisfactionScore: number;
    averageCookingTimeReduction: number;
    averageNutritionAchievementRate: number;
    standardDeviationSatisfaction: number;
    standardDeviationCookingTime: number;
    medianSatisfactionScore: number;
    hasError: boolean;
    comparisonWithPreviousMonth?: {
      previousSuccessRate: number;
      currentSuccessRate: number;
      trend: 'improving' | 'declining' | 'stable';
      changePercentage: number;
    };
  }
  
   function calculateSegmentStatistics(
    input: CalculateSegmentStatisticsInput
  ): CalculateSegmentStatisticsResult {
    const { segmentId, segmentName, users } = input;
  
    if (!users || users.length === 0) {
      return {
        segmentId,
        segmentName,
        userCount: 0,
        averageSatisfactionScore: 0,
        averageCookingTimeReduction: 0,
        averageNutritionAchievementRate: 0,
        standardDeviationSatisfaction: 0,
        standardDeviationCookingTime: 0,
        medianSatisfactionScore: 0,
        hasError: false,
      };
    }
  
    const userCount = users.length;
  
    const satisfactionScores = users
      .map((u) => u.satisfactionScore ?? 0)
      .filter((s) => typeof s === 'number');
    const cookingTimeReductions = users
      .map((u) => u.cookingTimeReduction ?? 0)
      .filter((c) => typeof c === 'number');
    const nutritionAchievementRates = users
      .map((u) => u.nutritionAchievementRate ?? 0)
      .filter((n) => typeof n === 'number');
  
    const averageSatisfactionScore =
      satisfactionScores.length > 0
        ? satisfactionScores.reduce((a, b) => a + b, 0) / satisfactionScores.length
        : 0;
  
    const averageCookingTimeReduction =
      cookingTimeReductions.length > 0
        ? cookingTimeReductions.reduce((a, b) => a + b, 0) /
          cookingTimeReductions.length
        : 0;
  
    const averageNutritionAchievementRate =
      nutritionAchievementRates.length > 0
        ? nutritionAchievementRates.reduce((a, b) => a + b, 0) /
          nutritionAchievementRates.length
        : 0;
  
    const calculateStandardDeviation = (values: number[]): number => {
      if (values.length === 0) return 0;
      const mean = values.reduce((a, b) => a + b, 0) / values.length;
      const variance =
        values.reduce((sum, val) => sum + Math.pow(val - mean, 2), 0) /
        values.length;
      return Math.sqrt(variance);
    };
  
    const standardDeviationSatisfaction = calculateStandardDeviation(
      satisfactionScores
    );
    const standardDeviationCookingTime = calculateStandardDeviation(
      cookingTimeReductions
    );
  
    const calculateMedian = (values: number[]): number => {
      if (values.length === 0) return 0;
      const sorted = [...values].sort((a, b) => a - b);
      const mid = Math.floor(sorted.length / 2);
      if (sorted.length % 2 === 0) {
        return (sorted[mid - 1] + sorted[mid]) / 2;
      }
      return sorted[mid];
    };
  
    const medianSatisfactionScore = calculateMedian(satisfactionScores);
  
    return {
      segmentId,
      segmentName,
      userCount,
      averageSatisfactionScore,
      averageCookingTimeReduction,
      averageNutritionAchievementRate,
      standardDeviationSatisfaction,
      standardDeviationCookingTime,
      medianSatisfactionScore,
      hasError: false,
    };
  }
  return { calculateSegmentStatistics };
})();
export const calculateSegmentStatistics = __aivicBundle_61_calculateSegmentStatistics.calculateSegmentStatistics;
