const __aivicBundle_68_calculateMonthlyCostAggregation = (() => {
  function calculateMonthlyCostAggregation(input: {
    user_id: string;
    target_month: string;
    food_records: Array<{
      record_id: string;
      user_id: string;
      meal_date: string;
      expense_amount: number;
      satisfaction_score: number;
      ingredients: Array<{
        ingredient_name: string;
        ingredient_category: string;
        cost: number;
      }>;
    }>;
    monthly_budget: number;
    currency: string;
  }): {
    total_monthly_expense: number;
    budget_savings_rate: number;
    average_satisfaction_score: number;
    ingredient_wise_cost_analysis: { [key: string]: number };
    target_month: string;
    record_count: number;
    currency: string;
  } {
    if (!String(input.user_id).trim()) {
      throw new Error('user_id is required');
    }
  
    const { food_records, monthly_budget, target_month, currency } = input;
  
    // Calculate total monthly expense
    const total_monthly_expense = food_records.reduce(
      (sum, record) => sum + record.expense_amount,
      0
    );
  
    // Calculate budget savings rate
    const budget_savings_rate =
      monthly_budget > 0
        ? ((monthly_budget - total_monthly_expense) / monthly_budget) * 100
        : 0;
  
    // Calculate average satisfaction score
    const average_satisfaction_score =
      food_records.length > 0
        ? food_records.reduce((sum, record) => sum + record.satisfaction_score, 0) /
          food_records.length
        : 0;
  
    // Calculate ingredient-wise cost analysis by category
    const ingredient_wise_cost_analysis: { [key: string]: number } = {};
  
    food_records.forEach((record) => {
      record.ingredients.forEach((ingredient) => {
        const category = ingredient.ingredient_category;
        if (!ingredient_wise_cost_analysis[category]) {
          ingredient_wise_cost_analysis[category] = 0;
        }
        ingredient_wise_cost_analysis[category] += ingredient.cost;
      });
    });
  
    return {
      total_monthly_expense,
      budget_savings_rate,
      average_satisfaction_score,
      ingredient_wise_cost_analysis,
      target_month,
      record_count: food_records.length,
      currency,
    };
  }
  return { calculateMonthlyCostAggregation };
})();
export const calculateMonthlyCostAggregation = __aivicBundle_68_calculateMonthlyCostAggregation.calculateMonthlyCostAggregation;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateMonthlyCostAggregation */

/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateMonthlyCost exports=aggregateMonthlyCost */
const __aivicBundle_69_aggregateMonthlyCost = (() => {
  function aggregateMonthlyCost(input: {
    user_id: string;
    year_month: string;
    purchase_records: Array<{
      id: string;
      user_id: string;
      purchase_date: string;
      amount: number;
      food_item_id: string;
      quantity: number;
      unit_price: number;
    }>;
  }): {
    user_id: string;
    year_month: string;
    total_amount: number;
    purchase_count: number;
    average_purchase_amount: number;
    max_purchase_amount: number;
    min_purchase_amount: number;
    aggregated_at: string;
  } {
    const { user_id, year_month, purchase_records } = input;
  
    const filteredRecords = purchase_records.filter(
      (record) =>
        record.user_id === user_id &&
        record.purchase_date.startsWith(year_month)
    );
  
    if (filteredRecords.length === 0) {
      throw new Error(`購入記録が見つかりません: user_id=${user_id}, year_month=${year_month}`);
    }
  
    const amounts = filteredRecords.map((record) => record.amount);
    const total_amount = amounts.reduce((sum, amount) => sum + amount, 0);
    const purchase_count = filteredRecords.length;
    const average_purchase_amount = Math.round(total_amount / purchase_count);
    const max_purchase_amount = Math.max(...amounts);
    const min_purchase_amount = Math.min(...amounts);
    const aggregated_at = new Date().toISOString();
  
    return {
      user_id,
      year_month,
      total_amount,
      purchase_count,
      average_purchase_amount,
      max_purchase_amount,
      min_purchase_amount,
      aggregated_at,
    };
  }
  return { aggregateMonthlyCost };
})();
