/* AIVIC_FUNCTION_BUNDLE_START owner=generateNextMonthMenuPriorityConditions exports=generateNextMonthMenuPriorityConditions */
const __aivicBundle_74_generateNextMonthMenuPriorityConditions = (() => {
  function generateNextMonthMenuPriorityConditions(input: {
    userId: string;
    currentSatisfactionScore: number;
    currentCostReductionRate: number;
    candidateMenus: Array<{
      candidateMenuId: string;
      mealName: string;
      estimatedCost: number;
      estimatedSatisfactionScore: number;
      estimatedCostReductionRate: number;
      nutritionBalance?: Record<string, number>;
    }>;
    budget: number;
  }): PriorityConditionSet & { priorityConditions: Array<PriorityConditionSet> } {
    if (!input.userId || String(input.userId).trim() === "") {
      throw new Error("userId is required");
    }
    if (input.budget === undefined || input.budget === null || input.budget <= 0) {
      throw new Error("budget is required and must be positive");
    }
  
    const {
      currentSatisfactionScore,
      currentCostReductionRate,
      candidateMenus,
    } = input;
  
    const priorityConditions: Array<PriorityConditionSet> = [];
  
    if (!candidateMenus || candidateMenus.length === 0) {
      priorityConditions.push({
        budgetPriority: 50,
        nutritionPriority: 50,
        targetNutrients: [],
        mealGenerationStrategy: "balanced_optimization",
        costReductionTarget: 0,
        restrictedIngredients: [],
      });
    } else {
      const satisfactionWeight = 0.6;
      const costReductionWeight = 0.4;
  
      const rankedByScore = candidateMenus
        .map((menu) => {
          const combinedScore =
            menu.estimatedSatisfactionScore * satisfactionWeight +
            menu.estimatedCostReductionRate * costReductionWeight;
          return {
            ...menu,
            combinedScore,
          };
        })
        .sort((a, b) => b.combinedScore - a.combinedScore);
  
      const topMenus = rankedByScore.slice(0, Math.min(3, rankedByScore.length));
  
      topMenus.forEach((menu) => {
        const satisfactionDelta =
          menu.estimatedSatisfactionScore - currentSatisfactionScore;
        const costReductionDelta =
          menu.estimatedCostReductionRate - currentCostReductionRate;
  
        const budgetPriority = Math.max(
          0,
          Math.min(100, 50 + costReductionDelta * 5)
        );
        const nutritionPriority = Math.max(
          0,
          Math.min(100, 50 + satisfactionDelta * 10)
        );
  
        const targetNutrients: string[] = [];
        if (menu.nutritionBalance) {
          Object.entries(menu.nutritionBalance).forEach(([nutrient, balance]) => {
            if (typeof balance === "number" && balance < 0.85) {
              targetNutrients.push(nutrient);
            }
          });
        }
  
        const strategy =
          budgetPriority > nutritionPriority
            ? "low_cost_priority"
            : nutritionPriority > budgetPriority
              ? "nutrition_priority"
              : "balanced_optimization";
  
        const costReductionTarget = Math.max(
          0,
          currentCostReductionRate + costReductionDelta
        );
  
        priorityConditions.push({
          budgetPriority,
          nutritionPriority,
          targetNutrients,
          mealGenerationStrategy: strategy,
          costReductionTarget,
          restrictedIngredients: [],
        });
      });
    }
  
    return {
      budgetPriority: priorityConditions[0]?.budgetPriority ?? 50,
      nutritionPriority: priorityConditions[0]?.nutritionPriority ?? 50,
      targetNutrients: priorityConditions[0]?.targetNutrients ?? [],
      mealGenerationStrategy:
        priorityConditions[0]?.mealGenerationStrategy ?? "balanced_optimization",
      costReductionTarget: priorityConditions[0]?.costReductionTarget ?? 0,
      restrictedIngredients: priorityConditions[0]?.restrictedIngredients ?? [],
      priorityConditions,
    };
  }
  return { generateNextMonthMenuPriorityConditions };
})();
