const __aivicBundle_77_combineMultiplePriorityConditionsForMenuProposal = (() => {
  interface CombineMultiplePriorityConditionsForMenuProposalInput {
    candidateMenus: Array<{
      candidateMenuId: string;
      mealName: string;
      estimatedCost: number;
      estimatedSatisfactionScore: number;
      estimatedCostReductionRate: number;
      nutritionBalance?: Record<string, number>;
    }>;
    satisfactionWeight: number;
    costReductionWeight: number;
    targetBudget: number;
  }
  
  interface CombineMultiplePriorityConditionsForMenuProposalOutput {
    rankedProposals: Array<{
      candidateMenuId: string;
      mealName: string;
      estimatedCost: number;
      estimatedSatisfactionScore: number;
      estimatedCostReductionRate: number;
      nutritionBalance?: Record<string, number>;
      combinedScore: number;
    }>;
  }
  
   function combineMultiplePriorityConditionsForMenuProposal(
    input: CombineMultiplePriorityConditionsForMenuProposalInput
  ): CombineMultiplePriorityConditionsForMenuProposalOutput {
    const {
      candidateMenus,
      satisfactionWeight,
      costReductionWeight,
      targetBudget,
    } = input;
  
    if (!candidateMenus || candidateMenus.length === 0) {
      return {
        rankedProposals: [],
      };
    }
  
    if (targetBudget <= 0) {
      throw new Error("targetBudget must be greater than 0");
    }
  
    const scoredProposals = candidateMenus.map((menu) => {
      const satisfactionComponent =
        (menu.estimatedSatisfactionScore / 5.0) * satisfactionWeight * 100;
  
      const costReductionComponent =
        (menu.estimatedCostReductionRate / 100.0) * costReductionWeight * 100;
  
      const combinedScore = satisfactionComponent + costReductionComponent;
  
      const withinBudget = menu.estimatedCost <= targetBudget;
  
      return {
        ...menu,
        combinedScore,
        withinBudget,
      };
    });
  
    const rankedProposals = scoredProposals
      .sort((a, b) => b.combinedScore - a.combinedScore)
      .map(({ withinBudget, ...rest }) => rest);
  
    return {
      rankedProposals,
    };
  }
  return { combineMultiplePriorityConditionsForMenuProposal };
})();
