      input.proteinLimitGrams > 0
        ? (maxProtein / input.proteinLimitGrams) * 100
        : 100;
    const carbsComplianceRate =
      input.carbsLimitGrams > 0
        ? (maxCarbs / input.carbsLimitGrams) * 100
        : 100;
