    const detectedDate = new Date(pattern.detectedDate);
    if (isNaN(detectedDate.getTime())) {
      throw new Error('detectedDate must be a valid ISO 8601 date format');
    }
  
    // Validate restrictionType
    const validRestrictionTypes = ['allergen', 'dietary'];
    if (pattern.restrictionType && !validRestrictionTypes.includes(pattern.restrictionType)) {
      throw new Error('restrictionType must be one of: allergen, dietary');
    }
  
    // Validate and apply defaults for severityLevel
    let severityLevel = pattern.severityLevel;
    if (severityLevel === undefined) {
      severityLevel = 0;
      appliedDefaults.push('severityLevel');
    } else if (severityLevel < 0) {
      throw new Error('severityLevel must be a non-negative number');
    }
  
    // Validate and apply defaults for affectedMealCount
    let affectedMealCount = pattern.affectedMealCount;
    if (affectedMealCount === undefined) {
      affectedMealCount = 0;
      appliedDefaults.push('affectedMealCount');
    }
  
    // Validate and apply defaults for userSegmentImpact
    let userSegmentImpact = pattern.userSegmentImpact;
