const __aivicBundle_89_detectDietaryRestrictionConflicts = (() => {
  function detectDietaryRestrictionConflicts(params: any): any {
    const {
      existingMenus,
      newRestrictions,
      userId,
    } = params;
  
    if (!newRestrictions || newRestrictions.length === 0) {
      throw new Error('食事制限条件を正しく入力してください');
    }
  
    const menus = existingMenus || [];
    const restrictions = newRestrictions || [];
  
    const conflictingMenus: any[] = [];
    const nonConflictingMenus: any[] = [];
  
    for (const menu of menus) {
      const menuConflicts: any[] = [];
      let riskScore = 0;
  
      for (const restriction of restrictions) {
        if (restriction.type === 'salt' && restriction.limit_g !== undefined) {
          const actualSalt = menu.totalSalt_g || 0;
          if (actualSalt > restriction.limit_g) {
            const violationAmount = actualSalt - restriction.limit_g;
            const conflictingDishes = (menu.dishes || [])
              .filter((d: any) => (d.salt_g || 0) > 0)
              .map((d: any) => d.dishName);
  
            menuConflicts.push({
              type: 'salt',
              actual_g: actualSalt,
              limit_g: restriction.limit_g,
              violationAmount_g: violationAmount,
              severity: 'high',
              conflictingDishes,
            });
            riskScore += 5;
          }
        }
  
        if (restriction.type === 'allergen' && restriction.allergen) {
          const conflictingDishes = (menu.dishes || [])
            .filter((d: any) => {
              if (restriction.allergen === 'egg') {
                return d.contains_egg === true;
              }
              return false;
            })
            .map((d: any) => d.dishName);
  
          if (conflictingDishes.length > 0) {
            menuConflicts.push({
              type: 'allergen',
              allergen: restriction.allergen,
              severity: 'high',
              conflictingDishes,
            });
            riskScore += 5;
          }
        }
      }
  
      if (menuConflicts.length > 0) {
        conflictingMenus.push({
          menuId: menu.id,
          date: menu.date,
          conflicts: menuConflicts,
          riskScore,
        });
      } else {
        nonConflictingMenus.push({
          menuId: menu.id,
          date: menu.date,
          totalSalt_g: menu.totalSalt_g || 0,
        });
      }
    }
  
    const detectionTimestamp = new Date().toISOString();
  
    return {
      userId,
      newRestrictions: restrictions,
      conflictingMenus,
      nonConflictingMenus,
      detectionTimestamp,
    };
  }
  return { detectDietaryRestrictionConflicts };
})();
