    const allergenRestrictions = (input.dietaryRestrictions || []).filter(
      (r) => r.type === "allergen_avoidance"
    );
  
    const maxSodiumPerDay = sodiumLimitRestrictions[0]?.maxMgPerDay ?? 2000;
