  function processMultipleRestrictionConditions(
    input: any,
    menuCandidates: any[]
  ): any {
    const userId = input.userId;
    const timestamp = input.timestamp;
    const restrictions = input.restrictions || [];
  
    // Sort restrictions by priority (lower priority number = higher priority)
    const priorityOrder = restrictions
      .map((r: any) => ({ type: r.type, priority: r.priority }))
      .sort((a: any, b: any) => a.priority - b.priority);
  
    // Evaluate each menu against all restrictions
    const exclusionReasons: any[] = [];
    const filteredMenus: any[] = [];
  
    menuCandidates.forEach((menu: any) => {
      let meetsAllConditions = true;
      const failureReasons: any[] = [];
  
      // Check allergen restrictions (priority 1)
      const allergenRestriction = restrictions.find(
        (r: any) => r.type === 'allergen'
      );
      if (allergenRestriction) {
        const matchedAllergens = (menu.allergens || []).filter((allergen: string) =>
          allergenRestriction.conditions.includes(allergen)
        );
        if (matchedAllergens.length > 0) {
          meetsAllConditions = false;
          failureReasons.push({
            menuId: menu.id,
            reason: 'allergen_match',
            matchedAllergens
          });
        }
      }
  
      // Check nutrition restrictions (priority 2)
      const nutritionRestriction = restrictions.find(
        (r: any) => r.type === 'nutrition'
      );
      if (nutritionRestriction && meetsAllConditions) {
        const violatedNutrients: string[] = [];
  
        if (
          nutritionRestriction.conditions.includes('low_sodium') &&
          menu.nutrition?.sodium > 350
        ) {
          violatedNutrients.push('sodium');
        }
  
        if (
          nutritionRestriction.conditions.includes('low_carb') &&
          menu.nutrition?.carbs > 40
        ) {
          violatedNutrients.push('carbs');
        }
  
        if (violatedNutrients.length > 0) {
          meetsAllConditions = false;
          failureReasons.push({
            menuId: menu.id,
            reason: 'nutrition_violation',
            violatedNutrients
          });
        }
      }
  
      // Check cooking time restrictions (priority 3)
      const cookingTimeRestriction = restrictions.find(
        (r: any) => r.type === 'cookingTime'
      );
      if (cookingTimeRestriction && meetsAllConditions) {
        if (
          cookingTimeRestriction.conditions.includes('within_30min') &&
          menu.cookingTime > 30
        ) {
          meetsAllConditions = false;
          failureReasons.push({
            menuId: menu.id,
            reason: 'cooking_time_violation',
            exceededMinutes: menu.cookingTime - 30
          });
        }
      }
  
      if (meetsAllConditions) {
        filteredMenus.push({
          id: menu.id,
          name: menu.name,
          allergens: menu.allergens,
          nutrition: menu.nutrition,
          cookingTime: menu.cookingTime,
          meetsAllConditions: true
        });
      } else {
        exclusionReasons.push(...failureReasons);
      }
    });
  
    const totalMenusEvaluated = menuCandidates.length;
    const totalMenusFiltered = filteredMenus.length;
    const filteringSuccessRate =
      totalMenusEvaluated > 0 ? totalMenusFiltered / totalMenusEvaluated : 0;
  
    return {
      userId,
      processedAt: timestamp,
      restrictionCount: restrictions.length,
      priorityOrder,
      filteredMenus,
      exclusionReasons,
      totalMenusEvaluated,
      totalMenusFiltered,
      filteringSuccessRate
    };
  }
  return { processMultipleRestrictionConditions };
