const __aivicBundle_103_calculateMonthlyCostSummary = (() => {
  interface CalculateMonthlyCostSummaryInput {
    user_id: string;
    target_month: string;
    transactions: Array<{
      transaction_id?: string;
      user_id?: string;
      transaction_date?: string;
      category: string;
      amount: number;
      description?: string;
    }>;
    budget_limit: number;
  }
  
  interface CalculateMonthlyCostSummaryResult {
    total_cost: number;
    difference_from_budget: number;
    is_over_budget: boolean;
    category_breakdown: Record<string, number>;
    target_month: string;
    budget_limit: number;
  }
  
   function calculateMonthlyCostSummary(
    input: CalculateMonthlyCostSummaryInput
  ): CalculateMonthlyCostSummaryResult {
    const { transactions, budget_limit, target_month } = input;
  
    let total_cost = 0;
    const category_breakdown: Record<string, number> = {};
  
    for (const transaction of transactions) {
      const { category, amount } = transaction;
      total_cost += amount;
  
      if (!category_breakdown[category]) {
        category_breakdown[category] = 0;
      }
      category_breakdown[category] += amount;
    }
  
    const difference_from_budget = total_cost - budget_limit;
    const is_over_budget = total_cost > budget_limit;
  
    return {
      total_cost,
      difference_from_budget,
      is_over_budget,
      category_breakdown,
      target_month,
      budget_limit
    };
  }
  return { calculateMonthlyCostSummary };
})();
