    if (input.homeFinanceSystemData.syncStatus !== 'connected') {
      throw new Error('家計管理システムとの連携が確立されていません');
    }
  
    const totalCost = input.purchaseRecords.reduce((sum, record) => {
      return sum + record.quantity * record.unitPrice;
    }, 0);
  
    const budgetDifference = input.budgetLimit - totalCost;
