/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateMonthlyCostExpenses exports=aggregateMonthlyCostExpenses */
const __aivicBundle_106_aggregateMonthlyCostExpenses = (() => {
  function aggregateMonthlyCostExpenses(input: {
    userId: string;
    timestamp: Date;
    expenses: Array<{ date: string; amount: number; categoryId: string }>;
    targetMonth?: string;
  }): {
    totalAmount: number;
    month: string;
    expenseCount: number;
  } {
    // Validate required inputs
    if (!input.userId || String(input.userId).trim() === '') {
      throw new Error('userId is required');
    }
    if (!input.timestamp) {
      throw new Error('timestamp is required');
    }
  
    const { expenses, targetMonth } = input;
  
    // Determine the target month for filtering
    let filterMonth = targetMonth;
    if (!filterMonth && expenses.length > 0) {
      const firstExpenseDate = expenses[0].date;
      filterMonth = firstExpenseDate.substring(0, 7);
    }
  
    // Filter expenses by the target month
    const filteredExpenses = expenses.filter((expense) => {
      const expenseMonth = expense.date.substring(0, 7);
      return expenseMonth === filterMonth;
    });
  
    // Calculate total amount
    const totalAmount = filteredExpenses.reduce((sum, expense) => sum + expense.amount, 0);
  
    return {
      totalAmount,
      month: filterMonth || '',
      expenseCount: filteredExpenses.length,
    };
  }
  return { aggregateMonthlyCostExpenses };
})();
