/* AIVIC_FUNCTION_BUNDLE_START owner=calculateImprovementGap exports=calculateImprovementGap */
const __aivicBundle_109_calculateImprovementGap = (() => {
  function calculateImprovementGap(
    insufficientNutrients: Array<{
      nutrientId: string;
      nutrientName: string;
      actualValue: number;
      unit: string;
    }>,
    nutritionStandards: Array<{
      nutrientId: string;
      nutrientName: string;
      targetValue: number;
      unit: string;
    }>
  ): Array<{
    nutrientId: string;
    nutrientName: string;
    gap: number;
    unit: string;
    gapPercentage: number;
  }> {
    const standardMap = new Map(
      nutritionStandards.map((s) => [s.nutrientId, s])
    );
  
    return insufficientNutrients.map((nutrient) => {
      const standard = standardMap.get(nutrient.nutrientId);
      if (!standard) {
        return {
          nutrientId: nutrient.nutrientId,
          nutrientName: nutrient.nutrientName,
          gap: 0,
          unit: nutrient.unit,
          gapPercentage: 0.0,
        };
      }
  
      const gap = standard.targetValue - nutrient.actualValue;
      const gapPercentage =
        standard.targetValue > 0
          ? Math.round(
              ((gap / standard.targetValue) * 100 + Number.EPSILON) * 100
            ) / 100
          : 0.0;
  
      return {
        nutrientId: nutrient.nutrientId,
        nutrientName: nutrient.nutrientName,
        gap: Math.round(gap * 100) / 100,
        unit: nutrient.unit,
        gapPercentage,
      };
    });
  }
  return { calculateImprovementGap };
})();
export const calculateImprovementGap = __aivicBundle_109_calculateImprovementGap.calculateImprovementGap;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateImprovementGap */

/* AIVIC_FUNCTION_BUNDLE_START owner=visualizeNutritionMetrics exports=visualizeNutritionMetrics */
const __aivicBundle_110_visualizeNutritionMetrics = (() => {
  interface VisualizeNutritionMetricsResult {
    summary: {
      totalNutrients: number;
      achievedNutrients: number;
      insufficientNutrients: number;
      averageAchievementScore: number;
    };
    metrics: Array<{
      nutrientId: string;
      nutrientName: string;
      achievementScore: number;
      gap: number;
      gapPercentage: number;
      unit: string;
      status: 'achieved' | 'partial' | 'insufficient';
      displayOrder: number;
    }>;
  }
  
   function visualizeNutritionMetrics(
    achievementScores: Array<{
      nutrientId: string;
      nutrientName: string;
      achievementScore: number;
    }>,
    improvementGaps: Array<{
      nutrientId: string;
      nutrientName: string;
      gap: number;
      gapPercentage: number;
      unit: string;
    }>,
    insufficientNutrients: Array<{
      nutrientId: string;
      nutrientName: string;
      achievementScore: number;
      priority: number;
    }>
  ): VisualizeNutritionMetricsResult {
    const metrics = achievementScores.map((score) => {
      const gap = improvementGaps.find((g) => g.nutrientId === score.nutrientId);
      const insufficient = insufficientNutrients.find(
        (i) => i.nutrientId === score.nutrientId
      );
  
      let status: 'achieved' | 'partial' | 'insufficient' = 'achieved';
      if (insufficient) {
        status = 'insufficient';
      } else if (score.achievementScore < 100) {
        status = 'partial';
      }
  
      const displayOrder = insufficient ? insufficient.priority : 999;
  
      return {
        nutrientId: score.nutrientId,
        nutrientName: score.nutrientName,
        achievementScore: score.achievementScore,
        gap: gap?.gap ?? 0,
        gapPercentage: gap?.gapPercentage ?? 0,
        unit: gap?.unit ?? '',
        status,
        displayOrder,
      };
    });
  
    const sortedMetrics = metrics.sort((a, b) => {
      if (a.displayOrder !== b.displayOrder) {
        return a.displayOrder - b.displayOrder;
      }
      return b.achievementScore - a.achievementScore;
    });
  
    const achievedCount = sortedMetrics.filter(
      (m) => m.status === 'achieved'
    ).length;
    const insufficientCount = sortedMetrics.filter(
      (m) => m.status === 'insufficient'
    ).length;
    const totalAchievementScore =
      sortedMetrics.reduce((sum, m) => sum + m.achievementScore, 0) /
      sortedMetrics.length;
  
    const summary = {
      totalNutrients: sortedMetrics.length,
      achievedNutrients: achievedCount,
      insufficientNutrients: insufficientCount,
      averageAchievementScore: Math.round(totalAchievementScore * 100) / 100,
    };
  
    return {
      summary,
      metrics: sortedMetrics,
    };
  }
  return { visualizeNutritionMetrics };
})();
export const visualizeNutritionMetrics = __aivicBundle_110_visualizeNutritionMetrics.visualizeNutritionMetrics;
