/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeOverbudgetFactorsByCategory exports=analyzeOverbudgetFactorsByCategory */
const __aivicBundle_113_analyzeOverbudgetFactorsByCategory = (() => {
  interface AnalyzeOverbudgetFactorsByCategoryInput {
    previousMonthData: Array<{
      categoryId: string;
      categoryName: string;
      unitPrice: number;
      quantity: number;
    }>;
    currentMonthData: Array<{
      categoryId: string;
      categoryName: string;
      unitPrice: number;
      quantity: number;
    }>;
    overbudgetAmount: number;
  }
  
  interface CategoryAnalysis {
    categoryId: string;
    categoryName: string;
    unitPriceChangeRate: number;
    quantity: number;
    contributionRate: number;
  }
  
  interface AnalyzeOverbudgetFactorsByCategoryResult {
    categories: CategoryAnalysis[];
    totalOverbudgetAmount: number;
    exportData: {
      csv: string;
      pdf: string;
    };
  }
  
   function analyzeOverbudgetFactorsByCategory(
    input: AnalyzeOverbudgetFactorsByCategoryInput
  ): AnalyzeOverbudgetFactorsByCategoryResult {
    const { previousMonthData, currentMonthData, overbudgetAmount } = input;
  
    // Build a map of current month data by categoryId for easy lookup
    const currentMonthMap = new Map(
      currentMonthData.map((item) => [item.categoryId, item])
    );
  
    // Calculate unit price change rate and contribution for each category
    const categoryAnalyses: CategoryAnalysis[] = previousMonthData
      .map((prevItem) => {
        const currItem = currentMonthMap.get(prevItem.categoryId);
        if (!currItem) {
          return null;
        }
  
        // Calculate unit price change rate: ((current - previous) / previous) * 100
        const unitPriceChangeRate =
          ((currItem.unitPrice - prevItem.unitPrice) / prevItem.unitPrice) * 100;
  
        // Calculate the cost increase for this category
        const costIncrease =
          (currItem.unitPrice - prevItem.unitPrice) * currItem.quantity;
  
        // Calculate contribution rate: (cost increase / total overbudget amount) * 100
        const contributionRate =
          overbudgetAmount > 0
            ? (costIncrease / overbudgetAmount) * 100
            : 0;
  
        return {
          categoryId: prevItem.categoryId,
          categoryName: prevItem.categoryName,
          unitPriceChangeRate,
          quantity: currItem.quantity,
          contributionRate,
        };
      })
      .filter((item): item is CategoryAnalysis => item !== null);
  
    // Sort by contribution rate in descending order
    categoryAnalyses.sort((a, b) => b.contributionRate - a.contributionRate);
  
    // Generate CSV export data
    const csvHeader = 'categoryId,categoryName,unitPriceChangeRate,quantity,contributionRate\n';
    const csvRows = categoryAnalyses
      .map(
        (cat) =>
          `${cat.categoryId},${cat.categoryName},${cat.unitPriceChangeRate.toFixed(2)},${cat.quantity},${cat.contributionRate.toFixed(2)}`
      )
      .join('\n');
    const csvData = csvHeader + csvRows;
  
    // Generate PDF export data (simplified representation)
    const pdfData = `Overbudget Analysis Report\n\nTotal Overbudget Amount: ${overbudgetAmount} yen\n\nCategory Breakdown:\n${categoryAnalyses
      .map(
        (cat) =>
          `${cat.categoryName}: ${cat.contributionRate.toFixed(2)}% (Unit Price Change: ${cat.unitPriceChangeRate.toFixed(2)}%)`
      )
      .join('\n')}`;
  
    return {
      categories: categoryAnalyses,
      totalOverbudgetAmount: overbudgetAmount,
      exportData: {
        csv: csvData,
        pdf: pdfData,
      },
    };
  }
  return { analyzeOverbudgetFactorsByCategory };
})();
export const analyzeOverbudgetFactorsByCategory = __aivicBundle_113_analyzeOverbudgetFactorsByCategory.analyzeOverbudgetFactorsByCategory;
/* AIVIC_FUNCTION_BUNDLE_END owner=analyzeOverbudgetFactorsByCategory */

/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeMonthlyExpenseExcess exports=analyzeMonthlyExpenseExcess */
const __aivicBundle_114_analyzeMonthlyExpenseExcess = (() => {
  interface AnalyzeMonthlyExpenseExcessInput {
    userId: string;
    targetMonth: string;
    monthlyBudget?: number;
    expenseRecords: Array<{
      id: string;
      userId: string;
      date: string;
      amount: number;
      category: string;
      aggregatedFlag: boolean;
    }>;
  }
  
  interface AnalyzeMonthlyExpenseExcessResult {
    userId: string;
    targetMonth: string;
    totalExpense: number;
    monthlyBudget?: number;
    excessAmount: number;
    isExceeded: boolean;
    categoryBreakdown: Record<string, number>;
    unitPriceVariationAnalysis?: {
      averageUnitPrice: number;
      priceChangePercentage: number;
    };
  }
  
   function analyzeMonthlyExpenseExcess(
    input: AnalyzeMonthlyExpenseExcessInput
  ): AnalyzeMonthlyExpenseExcessResult {
    const { userId, targetMonth, monthlyBudget, expenseRecords } = input;
  
    // Validation: Check if expenseRecords is empty
    if (!expenseRecords || expenseRecords.length === 0) {
      throw new Error(`月次集計データが存在しません: ${targetMonth}`);
    }
  
    // Validation: Check if all records have consistent aggregatedFlag
    const aggregatedFlags = expenseRecords.map((record) => record.aggregatedFlag);
    const allAggregated = aggregatedFlags.every((flag) => flag === true);
    const allNotAggregated = aggregatedFlags.every((flag) => flag === false);
  
    if (!allAggregated && !allNotAggregated) {
      throw new Error(`月次集計フラグが混在しています: ${targetMonth}`);
    }
  
    if (!allAggregated) {
      throw new Error(`月次集計されていないデータが含まれています: ${targetMonth}`);
    }
  
    // Calculate total expense and category breakdown
    let totalExpense = 0;
    const categoryBreakdown: Record<string, number> = {};
  
    for (const record of expenseRecords) {
      totalExpense += record.amount;
      if (!categoryBreakdown[record.category]) {
        categoryBreakdown[record.category] = 0;
      }
      categoryBreakdown[record.category] += record.amount;
    }
  
    // Calculate excess amount and isExceeded flag
    const budget = monthlyBudget || 0;
    const excessAmount = totalExpense > budget ? totalExpense - budget : 0;
    const isExceeded = totalExpense > budget;
  
    const result: AnalyzeMonthlyExpenseExcessResult = {
      userId,
      targetMonth,
      totalExpense,
      excessAmount,
      isExceeded,
      categoryBreakdown,
    };
  
    if (monthlyBudget !== undefined) {
      result.monthlyBudget = monthlyBudget;
    }
  
    // Calculate unitPriceVariationAnalysis if there are records
    if (expenseRecords.length > 0) {
      const averageUnitPrice = totalExpense / expenseRecords.length;
      const priceChangePercentage =
        expenseRecords.length > 1
          ? ((expenseRecords[expenseRecords.length - 1].amount - expenseRecords[0].amount) /
              expenseRecords[0].amount) *
            100
          : 0;
  
      result.unitPriceVariationAnalysis = {
        averageUnitPrice,
        priceChangePercentage,
      };
    }
  
    return result;
  }
  return { analyzeMonthlyExpenseExcess };
})();
export const analyzeMonthlyExpenseExcess = __aivicBundle_114_analyzeMonthlyExpenseExcess.analyzeMonthlyExpenseExcess;
/* AIVIC_FUNCTION_BUNDLE_END owner=analyzeMonthlyExpenseExcess */

