/* AIVIC_FUNCTION_BUNDLE_START owner=prioritizeNutritionDeficiencies exports=prioritizeNutritionDeficiencies */
const __aivicBundle_117_prioritizeNutritionDeficiencies = (() => {
  function prioritizeNutritionDeficiencies(
    input: any
  ): Array<{
    nutrientId: string;
    nutrientName: string;
    priorityScore: number;
  }> {
    // Handle null, undefined, or empty array
    if (input === null || input === undefined) {
      return [];
    }
  
    if (Array.isArray(input)) {
      if (input.length === 0) {
        return [];
      }
  
      // Validate improvementEffectScore for all items
      for (const item of input) {
        if (
          item.improvementEffectScore === null ||
          item.improvementEffectScore === undefined ||
          typeof item.improvementEffectScore !== 'number' ||
          isNaN(item.improvementEffectScore) ||
          item.improvementEffectScore < 0 ||
          item.improvementEffectScore > 100
        ) {
          throw new Error(
            `改善効果スコアが無効です: ${item.nutrientId} の改善効果スコアは 0 から 100 の数値である必要があります`
          );
        }
      }
  
      // Sort by improvementEffectScore in descending order
      const sorted = [...input].sort(
        (a, b) => b.improvementEffectScore - a.improvementEffectScore
      );
  
      return sorted.map((item) => ({
        nutrientId: item.nutrientId,
        nutrientName: item.nutrientName,
        priorityScore: item.improvementEffectScore,
      }));
    }
  
    // Handle object with insufficientItems property
    if (typeof input === 'object' && input !== null) {
      if (
        input.insufficientItems === null ||
        input.insufficientItems === undefined ||
        input.totalCount === 0
      ) {
        return [];
      }
  
      if (Array.isArray(input.insufficientItems)) {
        if (input.insufficientItems.length === 0) {
          return [];
        }
  
        // Validate improvementEffectScore for all items
        for (const item of input.insufficientItems) {
          if (
            item.improvementEffectScore === null ||
            item.improvementEffectScore === undefined ||
            typeof item.improvementEffectScore !== 'number' ||
            isNaN(item.improvementEffectScore) ||
            item.improvementEffectScore < 0 ||
            item.improvementEffectScore > 100
          ) {
            throw new Error(
              `改善効果スコアが無効です: ${item.nutrientId} の改善効果スコアは 0 から 100 の数値である必要があります`
            );
          }
        }
  
        // Sort by improvementEffectScore in descending order
        const sorted = [...input.insufficientItems].sort(
          (a, b) => b.improvementEffectScore - a.improvementEffectScore
        );
  
        return sorted.map((item) => ({
          nutrientId: item.nutrientId,
          nutrientName: item.nutrientName,
          priorityScore: item.improvementEffectScore,
        }));
      }
    }
  
    return [];
  }
  return { prioritizeNutritionDeficiencies };
})();
