/* AIVIC_FUNCTION_BUNDLE_START owner=determineMenuPriorityConditionSet exports=determineMenuPriorityConditionSet */
const __aivicBundle_119_determineMenuPriorityConditionSet = (() => {
  function determineMenuPriorityConditionSet(monthlyAnalysisData: any): any {
    const {
      foodBudgetLimit,
      foodActualAmount,
      budgetExcessFlag,
      nutritionAchievementData,
      allNutrientsFulfilledFlag,
    } = monthlyAnalysisData;
  
    // 予算差分を計算
    const budgetDifferenceAmount = foodBudgetLimit - foodActualAmount;
    const budgetDifferencePercent =
      (budgetDifferenceAmount / foodBudgetLimit) * 100;
  
    // 栄養達成率の平均を計算
    const nutritionAchievementRates = nutritionAchievementData.map(
      (item: any) => item.achievementRatePercent
    );
    const averageNutritionFulfillmentScore =
      nutritionAchievementRates.reduce((a: number, b: number) => a + b, 0) /
      nutritionAchievementRates.length;
  
    // 予算遵守スコア（実績 / 予算 * 100）
    const budgetAdherenceScore = (foodActualAmount / foodBudgetLimit) * 100;
  
    // 全体信度スコア：超過なし＆全栄養充足で高信度
    const overallDecisionConfidenceScore = !budgetExcessFlag
      ? averageNutritionFulfillmentScore > 100
        ? 99.5
        : 98.0
      : 75.0;
  
    // 不足栄養素リスト
    const insufficientNutrients = nutritionAchievementData
      .filter((item: any) => item.achievementStatus !== "達成")
      .map((item: any) => item.nutrientName);
  
    // 優先条件セットタイプと詳細を決定
    let priorityConditionSetType: string;
    let priorityConditionSetDetails: any;
    let recommendedAction: string;
  
    if (!budgetExcessFlag && allNutrientsFulfilledFlag) {
      // 維持型：食費超過なく栄養充足
      priorityConditionSetType = "maintenance";
      recommendedAction = "maintain_current_menu_balance";
      priorityConditionSetDetails = {
        priorityFocus: "nutritional_balance_maintenance",
        budgetOptimization: "relaxed",
        noveltyIntroduction: "low",
        familyPreferenceWeight: 0.6,
        nutritionalBalanceWeight: 0.3,
        budgetWeight: 0.1,
        menuDiversityLevel: "standard",
        costOptimizationLevel: "none",
        additionalConstraints: [],
      };
    } else if (budgetExcessFlag && !allNutrientsFulfilledFlag) {
      // 改善型：食費超過＆栄養不足
      priorityConditionSetType = "improvement";
      recommendedAction = "cost_reduction_and_nutrition_enhancement";
      priorityConditionSetDetails = {
        priorityFocus: "cost_reduction_and_nutrition_enhancement",
        budgetOptimization: "aggressive",
        noveltyIntroduction: "medium",
        familyPreferenceWeight: 0.3,
        nutritionalBalanceWeight: 0.5,
        budgetWeight: 0.2,
        menuDiversityLevel: "enhanced",
        costOptimizationLevel: "high",
        additionalConstraints: ["reduce_high_cost_ingredients"],
      };
    } else if (budgetExcessFlag && allNutrientsFulfilledFlag) {
      // 最適化型：食費超過だが栄養充足
      priorityConditionSetType = "optimization";
      recommendedAction = "cost_reduction_with_nutrition_maintenance";
      priorityConditionSetDetails = {
        priorityFocus: "cost_reduction_with_nutrition_maintenance",
        budgetOptimization: "moderate",
        noveltyIntroduction: "low",
        familyPreferenceWeight: 0.4,
        nutritionalBalanceWeight: 0.4,
        budgetWeight: 0.2,
        menuDiversityLevel: "standard",
        costOptimizationLevel: "moderate",
        additionalConstraints: ["maintain_nutrition_while_reducing_cost"],
      };
    } else {
      // 拡張型：食費内だが栄養不足
      priorityConditionSetType = "expansion";
      recommendedAction = "nutrition_enhancement_within_budget";
      priorityConditionSetDetails = {
        priorityFocus: "nutrition_enhancement_within_budget",
        budgetOptimization: "conservative",
        noveltyIntroduction: "medium",
        familyPreferenceWeight: 0.3,
        nutritionalBalanceWeight: 0.6,
        budgetWeight: 0.1,
        menuDiversityLevel: "enhanced",
        costOptimizationLevel: "none",
        additionalConstraints: ["prioritize_deficient_nutrients"],
      };
    }
  
    // 決定根拠メタデータ
    const decisionReason = {
      budgetStatus: budgetExcessFlag ? "exceeded" : "within_limit",
      budgetDifferenceAmount,
      budgetDifferencePercent,
      nutritionStatus: allNutrientsFulfilledFlag
        ? "all_fulfilled"
        : "has_deficiency",
      insufficientNutrients,
      recommendedAction,
    };
  
    // 意思決定スコア
    const decisionScore = {
      budgetAdherenceScore,
      nutritionFulfillmentScore:
        Math.round(averageNutritionFulfillmentScore * 10) / 10,
      overallDecisionConfidenceScore,
    };
  
    // 決定ID生成（UUID形式）
    const decisionId = randomUUID();
  
    // タイムスタンプ設定：処理時刻は現在時刻、有効期間は入力の分析月から導出
    const decidedAt = new Date().toISOString();
    
    // analysisMonth から次月の有効期間を計算
    const analysisDate = new Date(monthlyAnalysisData.analysisMonth || new Date());
    const nextMonth = new Date(analysisDate.getFullYear(), analysisDate.getMonth() + 1, 1);
    const nextMonthEnd = new Date(analysisDate.getFullYear(), analysisDate.getMonth() + 2, 0);
    
    const validFrom = nextMonth.toISOString().split('T')[0] + 'T00:00:00Z';
    const validUntil = nextMonthEnd.toISOString().split('T')[0] + 'T23:59:59Z';
  
    return {
      priorityConditionSetType,
      priorityConditionSetDetails,
      decisionReason,
      decisionScore,
      decidedAt,
      validFrom,
      validUntil,
      status: "determined",
      decisionId,
    };
  }
  return { determineMenuPriorityConditionSet };
})();
export const determineMenuPriorityConditionSet = __aivicBundle_119_determineMenuPriorityConditionSet.determineMenuPriorityConditionSet;
/* AIVIC_FUNCTION_BUNDLE_END owner=determineMenuPriorityConditionSet */

