/* AIVIC_FUNCTION_BUNDLE_START owner=determineMenuGenerationPriorityConditionSet exports=determineMenuGenerationPriorityConditionSet */
const __aivicBundle_121_determineMenuGenerationPriorityConditionSet = (() => {
  interface DetermineMenuGenerationPriorityConditionSetInput {
    userId?: string;
    analysisMonthYear?: string | null;
    nutritionStandardValues?: {
      [key: string]: { min: number; max: number; unit: string };
    };
    monthlyNutritionResults?: {
      proteinActual?: number;
      carbohydrateActual?: number;
      fatActual?: number;
    } | null;
    foodExpenseData?: {
      budgetLimit?: number;
      actualExpense?: number;
      overageFlag?: boolean;
    };
    familyPreferenceScores?: Array<{
      dishId: string;
      satisfactionScore: number;
    }>;
  }
  
   function determineMenuGenerationPriorityConditionSet(
    input: DetermineMenuGenerationPriorityConditionSetInput
  ): MealPriorityConditionSet & {
    priorityConditions: Array<{ condition: string; score: number }>;
    priorityMode: string;
    adjustmentFactors: { [key: string]: number };
  } {
    // Validation: Required fields
    if (!input.userId || input.userId === '') {
      throw new Error('userId は必須です。ユーザーID が指定されていません。');
    }
  
    if (input.analysisMonthYear === null || input.analysisMonthYear === undefined) {
      throw new Error('analysisMonthYear は必須です。分析対象月 が指定されていません。');
    }
  
    if (!input.nutritionStandardValues) {
      throw new Error('nutritionStandardValues は必須です。栄養基準値 が指定されていません。');
    }
  
    if (input.monthlyNutritionResults === null || input.monthlyNutritionResults === undefined) {
      throw new Error('monthlyNutritionResults は必須です。月次栄養摂取 データが指定されていません。');
    }
  
    if (!input.foodExpenseData) {
      throw new Error('foodExpenseData は必須です。食費 予算データが指定されていません。');
    }
  
    if (!input.familyPreferenceScores) {
      throw new Error('familyPreferenceScores は必須です。嗜好データ が指定されていません。');
    }
  
    // Validation: Required nested fields in nutritionStandardValues
    if (
      input.nutritionStandardValues.protein === undefined ||
      input.nutritionStandardValues.carbohydrate === undefined ||
      input.nutritionStandardValues.fat === undefined
    ) {
      throw new Error('nutritionStandardValues に必須の栄養基準値 が不足しています。');
    }
  
    // Validation: Required nested fields in monthlyNutritionResults
    if (
      input.monthlyNutritionResults.proteinActual === undefined ||
      input.monthlyNutritionResults.carbohydrateActual === undefined ||
      input.monthlyNutritionResults.fatActual === undefined
    ) {
      throw new Error('monthlyNutritionResults に必須の月次栄養摂取 フィールドが不足しています。');
    }
  
    // Validation: Required nested fields in foodExpenseData
    if (
      input.foodExpenseData.budgetLimit === undefined ||
      input.foodExpenseData.actualExpense === undefined ||
      input.foodExpenseData.overageFlag === undefined
    ) {
      throw new Error('foodExpenseData に必須の食費 フィールドが不足しています。');
    }
  
    // Validation: familyPreferenceScores must not be empty
    if (input.familyPreferenceScores.length === 0) {
      throw new Error('familyPreferenceScores は空配列です。嗜好データ が不足しています。');
    }
  
    // Calculate nutrition deficiency scores
    const proteinStandard = input.nutritionStandardValues.protein;
    const carbohydrateStandard = input.nutritionStandardValues.carbohydrate;
    const fatStandard = input.nutritionStandardValues.fat;
  
    const proteinDeficit = Math.max(
      0,
      ((proteinStandard.max - input.monthlyNutritionResults.proteinActual) / proteinStandard.max) * 100
    );
    const carbohydrateDeficit = Math.max(
      0,
      ((carbohydrateStandard.max - input.monthlyNutritionResults.carbohydrateActual) /
        carbohydrateStandard.max) *
        100
    );
    const fatDeficit = Math.max(
      0,
      ((fatStandard.max - input.monthlyNutritionResults.fatActual) / fatStandard.max) * 100
    );
  
    const maxNutritionDeficit = Math.max(proteinDeficit, carbohydrateDeficit, fatDeficit);
  
    // Calculate budget overage
    const budgetOverage = input.foodExpenseData.actualExpense - input.foodExpenseData.budgetLimit;
    const overagePercentage = (budgetOverage / input.foodExpenseData.budgetLimit) * 100;
  
    // Calculate priority scores
    const budgetPriority = Math.min(100, Math.max(0, 50 + overagePercentage * 2));
    const nutritionPriority = Math.min(100, Math.max(0, 50 + maxNutritionDeficit * 1.5));
  
    // Determine meal generation strategy
    let mealGenerationStrategy: 'low_cost_priority' | 'nutrition_priority' | 'balanced_optimization';
    let priorityMode: string;
  
    if (budgetPriority > 75) {
      mealGenerationStrategy = 'low_cost_priority';
      priorityMode = 'budget';
    } else if (nutritionPriority > 75) {
      mealGenerationStrategy = 'nutrition_priority';
      priorityMode = 'nutrition';
    } else {
      mealGenerationStrategy = 'balanced_optimization';
      priorityMode = 'preference';
    }
  
    // Calculate cost reduction target
    const costReductionTarget = Math.max(0, budgetOverage);
  
    // Identify target nutrients with deficits
    const targetNutrients: string[] = [];
    if (proteinDeficit > 10) targetNutrients.push('protein');
    if (carbohydrateDeficit > 10) targetNutrients.push('carbohydrate');
    if (fatDeficit > 10) targetNutrients.push('fat');
  
    // Determine restricted ingredients based on preference patterns
    const restrictedIngredients: string[] = [];
    const lowSatisfactionDishes = input.familyPreferenceScores.filter(
      (pref) => pref.satisfactionScore < 60
    );
    if (lowSatisfactionDishes.length > 0) {
      restrictedIngredients.push(
        ...lowSatisfactionDishes.map((dish) => `avoid_${dish.dishId}`)
      );
    }
  
    // Build priority conditions array
    const priorityConditions = [
      { condition: 'budget_priority', score: budgetPriority },
      { condition: 'nutrition_priority', score: nutritionPriority },
      { condition: 'preference_satisfaction', score: input.familyPreferenceScores.reduce((sum, pref) => sum + pref.satisfactionScore, 0) / input.familyPreferenceScores.length },
    ];
  
    // Build adjustment factors
    const adjustmentFactors = {
      budget_overage_percentage: overagePercentage,
      max_nutrition_deficit: maxNutritionDeficit,
      cost_reduction_target: costReductionTarget,
      target_nutrient_count: targetNutrients.length,
    };
  
    return {
      budgetPriority,
      nutritionPriority,
      targetNutrients,
      mealGenerationStrategy,
      costReductionTarget,
      restrictedIngredients,
      priorityConditions,
      priorityMode,
      adjustmentFactors,
    };
  }
  return { determineMenuGenerationPriorityConditionSet };
})();
export const determineMenuGenerationPriorityConditionSet = __aivicBundle_121_determineMenuGenerationPriorityConditionSet.determineMenuGenerationPriorityConditionSet;
/* AIVIC_FUNCTION_BUNDLE_END owner=determineMenuGenerationPriorityConditionSet */

