/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMonthlyAnalysisCycleSchedule exports=calculateMonthlyAnalysisCycleSchedule */
const __aivicBundle_123_calculateMonthlyAnalysisCycleSchedule = (() => {
  interface CalculateMonthlyAnalysisCycleScheduleInput {
    userId: string;
    cutoffDate: number;
    cycleType: "monthly";
    effectiveFromMonth: Date;
  }
  
  interface CalculateMonthlyAnalysisCycleScheduleOutput {
    cutoffDate: number;
    cycleName: string;
    dataCollectionStartDate: string;
    dataCollectionEndDate: string;
  }
  
   function calculateMonthlyAnalysisCycleSchedule(
    input: CalculateMonthlyAnalysisCycleScheduleInput
  ): CalculateMonthlyAnalysisCycleScheduleOutput {
    const { cutoffDate, effectiveFromMonth } = input;
  
    const effectiveYear = effectiveFromMonth.getUTCFullYear();
    const effectiveMonth = effectiveFromMonth.getUTCMonth();
  
    const cycleName = `${effectiveYear}-${String(effectiveMonth + 1).padStart(2, "0")}`;
  
    const previousMonth = effectiveMonth === 0 ? 11 : effectiveMonth - 1;
    const previousYear = effectiveMonth === 0 ? effectiveYear - 1 : effectiveYear;
  
    const dataCollectionEndDate = new Date(
      Date.UTC(previousYear, previousMonth, cutoffDate, 23, 59, 59, 999)
    );
  
    const dataCollectionStartDate = new Date(
      Date.UTC(previousYear, previousMonth - 1 === -1 ? 11 : previousMonth - 1, cutoffDate + 1, 0, 0, 0, 0)
    );
  
    if (previousMonth - 1 === -1) {
      dataCollectionStartDate.setUTCFullYear(previousYear - 1);
    }
  
    return {
      cutoffDate,
      cycleName,
      dataCollectionStartDate: dataCollectionStartDate.toISOString(),
      dataCollectionEndDate: dataCollectionEndDate.toISOString(),
    };
  }
  return { calculateMonthlyAnalysisCycleSchedule };
})();
