/* AIVIC_FUNCTION_BUNDLE_END owner=calculateMonthlyAnalysisCycleSchedule */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateCutoffDateConsistency exports=validateCutoffDateConsistency */
const __aivicBundle_124_validateCutoffDateConsistency = (() => {
  function validateCutoffDateConsistency(
    input: Array<{
      cutoffDate?: number;
      cycleName?: string;
      dataCollectionStartDate?: string | Date;
      dataCollectionEndDate?: string | Date;
    }> | {
      cutoffDate: Date;
      mealRecordDates: Date[];
      purchaseRecordDates: Date[];
      nutritionDataDates: Date[];
    }
  ): boolean | {
    isConsistent: boolean;
    inconsistentRecords: Array<{
      recordType: string;
      recordDate: Date;
      cutoffDate: Date;
    }>;
    validationStatus: string;
  } {
    // Handle array input (from test: array of schedule objects)
    if (Array.isArray(input)) {
      const schedules = input as Array<{
        cutoffDate?: number;
        cycleName?: string;
        dataCollectionStartDate?: string | Date;
        dataCollectionEndDate?: string | Date;
      }>;
  
      if (schedules.length === 0) {
        return true;
      }
  
      // Extract cutoff dates from all schedules
      const cutoffDates = schedules
        .map(s => s.cutoffDate)
        .filter((d): d is number => d !== undefined);
  
      // Check if all schedules have the same cutoff date
      if (cutoffDates.length === 0) {
        return true;
      }
  
      const firstCutoffDate = cutoffDates[0];
      const allConsistent = cutoffDates.every(d => d === firstCutoffDate);
  
      // Verify that dataCollectionEndDate matches the cutoff date
      const dateConsistencies = schedules.map(schedule => {
        if (!schedule.dataCollectionEndDate) {
          return true;
        }
  
        const endDate = new Date(schedule.dataCollectionEndDate);
        const endDateDay = endDate.getUTCDate();
  
        return schedule.cutoffDate === undefined || endDateDay === schedule.cutoffDate;
      });
  
      const allDateConsistent = dateConsistencies.every(c => c === true);
  
      return allConsistent && allDateConsistent;
    }
  
    // Handle object input (from signature: cutoff date with record dates)
    const typedInput = input as {
      cutoffDate: Date;
      mealRecordDates: Date[];
      purchaseRecordDates: Date[];
      nutritionDataDates: Date[];
    };
  
    const cutoffDate = typedInput.cutoffDate;
    const allRecordDates = [
      ...typedInput.mealRecordDates.map(d => ({ date: d, type: 'meal' })),
      ...typedInput.purchaseRecordDates.map(d => ({ date: d, type: 'purchase' })),
      ...typedInput.nutritionDataDates.map(d => ({ date: d, type: 'nutrition' })),
    ];
  
    const inconsistentRecords: Array<{
      recordType: string;
      recordDate: Date;
      cutoffDate: Date;
    }> = [];
  
    for (const record of allRecordDates) {
      if (record.date > cutoffDate) {
        inconsistentRecords.push({
          recordType: record.type,
          recordDate: record.date,
          cutoffDate,
        });
      }
    }
  
    const isConsistent = inconsistentRecords.length === 0;
  
    return {
      isConsistent,
      inconsistentRecords,
      validationStatus: isConsistent ? 'valid' : 'invalid',
    };
  }
  return { validateCutoffDateConsistency };
})();
export const validateCutoffDateConsistency = __aivicBundle_124_validateCutoffDateConsistency.validateCutoffDateConsistency;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateCutoffDateConsistency */

/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateDataByCutoffDate exports=aggregateDataByCutoffDate */
const __aivicBundle_125_aggregateDataByCutoffDate = (() => {
  function aggregateDataByCutoffDate(input: {
    userId: string;
    startDate: Date;
    endDate: Date;
    cutoffDate: number;
  }): {
    periodStart: Date;
    periodEnd: Date;
    dataPoints: number;
  } {
    const { userId, startDate, endDate, cutoffDate } = input;
  
    // Validate that startDate and endDate are valid dates
    if (!(startDate instanceof Date) || isNaN(startDate.getTime())) {
      throw new Error("startDate must be a valid Date");
    }
    if (!(endDate instanceof Date) || isNaN(endDate.getTime())) {
      throw new Error("endDate must be a valid Date");
    }
  
    // Validate that startDate <= endDate
    if (startDate > endDate) {
      throw new Error("startDate must be less than or equal to endDate");
    }
  
    // Validate cutoffDate is a valid day of month (1-31)
    if (!Number.isInteger(cutoffDate) || cutoffDate < 1 || cutoffDate > 31) {
      throw new Error("cutoffDate must be an integer between 1 and 31");
    }
  
    // Validate userId is provided
    if (!userId || typeof userId !== "string") {
      throw new Error("userId must be a non-empty string");
    }
  
    // Calculate the number of data points within the period
    // This represents the number of days in the aggregation period
    const timeDiffMs = endDate.getTime() - startDate.getTime();
    const dataPoints = Math.floor(timeDiffMs / (1000 * 60 * 60 * 24)) + 1;
  
    return {
      periodStart: startDate,
      periodEnd: endDate,
      dataPoints: Math.max(0, dataPoints),
    };
  }
  return { aggregateDataByCutoffDate };
})();
export const aggregateDataByCutoffDate = __aivicBundle_125_aggregateDataByCutoffDate.aggregateDataByCutoffDate;
/* AIVIC_FUNCTION_BUNDLE_END owner=aggregateDataByCutoffDate */

