/* AIVIC_FUNCTION_BUNDLE_START owner=validateMonthlyAnalysisCycleDuration exports=validateMonthlyAnalysisCycleDuration */
const __aivicBundle_127_validateMonthlyAnalysisCycleDuration = (() => {
  function validateMonthlyAnalysisCycleDuration(input: {
    cycleDurationDays: number;
    analysisStartDate: Date;
    analysisEndDate: Date;
  }): {
    warningFlag: boolean;
    exceedsDays: number;
    warningMessage: string;
  } {
    if (input.cycleDurationDays === undefined || input.cycleDurationDays === null) {
      throw new Error("cycleDurationDays is required");
    }
  
    const startDate = new Date(input.analysisStartDate);
    const endDate = new Date(input.analysisEndDate);
  
    const timeDiffMs = endDate.getTime() - startDate.getTime();
    const actualDurationDays = Math.ceil(timeDiffMs / (1000 * 60 * 60 * 24));
  
    const expectedDurationDays = 7;
    const exceedsDays = Math.max(0, actualDurationDays - expectedDurationDays);
    const warningFlag = exceedsDays > 0;
  
    let warningMessage = "";
    if (warningFlag) {
      warningMessage = `分析サイクルが7日を超過しています。超過日数: ${exceedsDays}日`;
    } else {
      warningMessage = `分析サイクルは正常範囲内です。実際の期間: ${actualDurationDays}日`;
    }
  
    return {
      warningFlag,
      exceedsDays,
      warningMessage,
    };
  }
  return { validateMonthlyAnalysisCycleDuration };
})();
export const validateMonthlyAnalysisCycleDuration = __aivicBundle_127_validateMonthlyAnalysisCycleDuration.validateMonthlyAnalysisCycleDuration;
