const __aivicBundle_135_calculateNextVerificationDate = (() => {
  function calculateNextVerificationDate(
    lastVerificationDate: Date | null,
    cycle: string | undefined
  ): Date {
    if (lastVerificationDate === null || lastVerificationDate === undefined) {
      throw new Error('前回検証日が指定されていません');
    }
  
    if (cycle === undefined || cycle === null || typeof cycle !== 'string') {
      throw new Error('検証周期が指定されていません');
    }
  
    if (cycle !== 'monthly') {
      throw new Error('無効な検証周期です');
    }
  
    const year = lastVerificationDate.getUTCFullYear();
    const month = lastVerificationDate.getUTCMonth();
    const date = lastVerificationDate.getUTCDate();
  
    let nextYear = year;
    let nextMonth = month + 1;
    let nextDate = date;
  
    if (nextMonth > 11) {
      nextMonth = 0;
      nextYear += 1;
    }
  
    const daysInNextMonth = new Date(nextYear, nextMonth + 1, 0).getUTCDate();
    if (nextDate > daysInNextMonth) {
      nextDate = daysInNextMonth;
    }
  
    return new Date(Date.UTC(nextYear, nextMonth, nextDate, 0, 0, 0, 0));
  }
  return { calculateNextVerificationDate };
})();
