    const alertMsg = isVerificationTimingArrived
      ? '検証タイミングに到達しました'
      : '検証タイミングに未到達です';
  
    const minimumDays = input.minimumCollectionDays ?? verificationCycleDays;
    const progressPercent = Math.round((daysPassed / minimumDays) * 100);
  
