/* AIVIC_FUNCTION_BUNDLE_START owner=validateNutritionVerificationCycle exports=validateNutritionVerificationCycle */
const __aivicBundle_138_validateNutritionVerificationCycle = (() => {
  function validateNutritionVerificationCycle(input: {
    verification_cycle_id: string;
    verification_cycle: any;
    verification_frequency: string;
    last_verification_date: Date;
    next_verification_date: Date;
    invalid?: any;
  }): {
    is_valid: boolean;
    verification_cycle_id: string;
    next_verification_date: Date;
    verification_frequency: string;
  } {
    // Validate verification_cycle is present and valid
    if (
      input.verification_cycle === null ||
      input.verification_cycle === undefined ||
      input.verification_cycle === '' ||
      typeof input.verification_cycle !== 'string'
    ) {
      throw new Error('検証周期情報が無効です');
    }
  
    // Validate verification_cycle value is one of allowed values
    const validCycles = ['monthly', 'quarterly', 'semi-annual', 'annual'];
    if (!validCycles.includes(input.verification_cycle)) {
      throw new Error('検証周期情報が無効です');
    }
  
    // Validate verification_frequency matches verification_cycle
    if (input.verification_frequency !== input.verification_cycle) {
      throw new Error('検証周期情報が無効です');
    }
  
    // Validate dates are valid Date objects
    if (!(input.last_verification_date instanceof Date) || isNaN(input.last_verification_date.getTime())) {
      throw new Error('検証周期情報が無効です');
    }
  
    if (!(input.next_verification_date instanceof Date) || isNaN(input.next_verification_date.getTime())) {
      throw new Error('検証周期情報が無効です');
    }
  
    // Return valid result
    return {
      is_valid: true,
      verification_cycle_id: input.verification_cycle_id,
      next_verification_date: input.next_verification_date,
      verification_frequency: input.verification_frequency,
    };
  }
  return { validateNutritionVerificationCycle };
})();
