const __aivicBundle_139_instructDataCollection = (() => {
  interface InstructDataCollectionConfig {
    verificationCycleType?: string;
    verificationScheduleTime?: string;
    collectionPeriodDays: number;
    minimumSampleCount: number;
    userId: string;
    familyMemberId?: string;
  }
  
  interface InstructDataCollectionInput {
    config?: InstructDataCollectionConfig;
    currentTime?: Date;
    minimum_sample_count?: number;
    available_sample_count?: number;
    collection_period?: string;
  }
  
  interface InstructDataCollectionResult {
    collectionPeriodDays: number;
    minimumSampleCount: number;
    collectionStartDate: Date;
    collectionEndDate: Date;
    collectionStatus: string;
    userId: string;
    familyMemberId?: string;
    instructionIssuedAt: Date;
    nextVerificationScheduledTime: Date;
  }
  
   function instructDataCollection(
    input: InstructDataCollectionInput
  ): InstructDataCollectionResult {
    // Handle snake_case validation error case
    if (
      input.minimum_sample_count !== undefined &&
      input.available_sample_count !== undefined
    ) {
      if (input.minimum_sample_count > input.available_sample_count) {
        throw new Error(
          `最小サンプル数 ${input.minimum_sample_count} が収集可能なサンプル数 ${input.available_sample_count} を超えています`
        );
      }
    }
  
    // Handle camelCase config case
    if (input.config) {
      const config = input.config;
      const currentTime = input.currentTime || new Date();
  
      // Calculate collection start date: currentTime - collectionPeriodDays
      const collectionStartDate = new Date(currentTime);
      collectionStartDate.setDate(
        collectionStartDate.getDate() - config.collectionPeriodDays
      );
  
      // Calculate next verification scheduled time based on cycle type
      let nextVerificationScheduledTime = new Date(currentTime);
      if (config.verificationCycleType === "monthly") {
        nextVerificationScheduledTime.setMonth(
          nextVerificationScheduledTime.getMonth() + 1
        );
      }
  
      return {
        collectionPeriodDays: config.collectionPeriodDays,
        minimumSampleCount: config.minimumSampleCount,
        collectionStartDate,
        collectionEndDate: currentTime,
        collectionStatus: "started",
        userId: config.userId,
        familyMemberId: config.familyMemberId,
        instructionIssuedAt: currentTime,
        nextVerificationScheduledTime,
      };
    }
  
    // Fallback for unexpected input shape
    throw new Error("Invalid input: config and currentTime are required");
  }
  return { instructDataCollection };
})();
export const instructDataCollection = __aivicBundle_139_instructDataCollection.instructDataCollection;
/* AIVIC_FUNCTION_BUNDLE_END owner=instructDataCollection */

/* AIVIC_FUNCTION_BUNDLE_START owner=collectUserFoodRecordData exports=collectUserFoodRecordData */
const __aivicBundle_140_collectUserFoodRecordData = (() => {
  interface CollectUserFoodRecordDataInput {
    verificationType: 'monthly' | 'quarterly';
    currentDate: Date;
  }
  
  interface CollectUserFoodRecordDataResult {
    periodStart: string;
    periodEnd: string;
    collectionPeriodDays: number;
    instructionStatus: 'initiated';
    targetPeriod: {
      type: 'monthly' | 'quarterly';
      start: string;
      end: string;
    };
    includesEndDate: boolean;
    minimumSampleSize: number;
    collectedRecordsCount: number;
    executionResult: {
      success: boolean;
      periodValidation: 'passed';
      dataCollectionStatus: 'completed';
    };
  }
  
   function collectUserFoodRecordData(
    input: CollectUserFoodRecordDataInput
  ): CollectUserFoodRecordDataResult {
    const { verificationType, currentDate } = input;
  
    let periodStart: string;
    let periodEnd: string;
    let collectionPeriodDays: number;
  
    if (verificationType === 'monthly') {
      const year = currentDate.getUTCFullYear();
      const month = currentDate.getUTCMonth();
  
      periodStart = `${year}-${String(month + 1).padStart(2, '0')}-01`;
  
      const lastDay = new Date(Date.UTC(year, month + 1, 0));
      const lastDayOfMonth = lastDay.getUTCDate();
      periodEnd = `${year}-${String(month + 1).padStart(2, '0')}-${String(lastDayOfMonth).padStart(2, '0')}`;
  
      collectionPeriodDays = lastDayOfMonth;
    } else {
      const year = currentDate.getUTCFullYear();
      const month = currentDate.getUTCMonth();
  
      const quarterStartMonth = Math.floor(month / 3) * 3;
      const quarterStartDate = new Date(Date.UTC(year, quarterStartMonth, 1));
      const quarterEndDate = new Date(Date.UTC(year, quarterStartMonth + 3, 0));
  
      periodStart = `${quarterStartDate.getUTCFullYear()}-${String(quarterStartDate.getUTCMonth() + 1).padStart(2, '0')}-01`;
      periodEnd = `${quarterEndDate.getUTCFullYear()}-${String(quarterEndDate.getUTCMonth() + 1).padStart(2, '0')}-${String(quarterEndDate.getUTCDate()).padStart(2, '0')}`;
  
      const startDate = new Date(Date.UTC(year, quarterStartMonth, 1));
      const endDate = new Date(Date.UTC(year, quarterStartMonth + 3, 0));
      collectionPeriodDays = Math.floor((endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24)) + 1;
    }
  
    return {
      periodStart,
      periodEnd,
      collectionPeriodDays,
      instructionStatus: 'initiated',
      targetPeriod: {
        type: verificationType,
        start: periodStart,
        end: periodEnd,
      },
      includesEndDate: true,
      minimumSampleSize: 1,
      collectedRecordsCount: 0,
      executionResult: {
        success: true,
        periodValidation: 'passed',
        dataCollectionStatus: 'completed',
      },
    };
  }
  return { collectUserFoodRecordData };
})();
