const __aivicBundle_144_calculateNutrientAchievementScores = (() => {
  function calculateNutrientAchievementScores(
    userData: {
      age: number;
      gender: 'male' | 'female';
      activityLevel: 'sedentary' | 'light' | 'moderate' | 'active' | 'very_active';
    },
    intakeData: {
      userId: string;
      date: string;
      nutrients: {
        protein?: { intake: number; unit: string };
        fat?: { intake: number; unit: string };
        carbohydrate?: { intake: number; unit: string };
        vitaminA?: { intake: number; unit: string };
        vitaminC?: { intake: number; unit: string };
        calcium?: { intake: number; unit: string };
        iron?: { intake: number; unit: string };
        [key: string]: { intake: number; unit: string } | undefined;
      };
    }
  ): Record<string, number> {
    if (!String(intakeData.userId).trim()) {
      throw new Error('userId is required');
    }
    if (!String(intakeData.date).trim()) {
      throw new Error('date is required');
    }
  
    const nutritionStandards: Record<string, number> = {
      protein: 60,
      fat: 70,
      carbohydrate: 350,
      vitaminA: 800,
      vitaminC: 100,
      calcium: 800,
      iron: 8,
    };
  
    const result: Record<string, number> = {};
  
    for (const [nutrientName, standard] of Object.entries(nutritionStandards)) {
      const intakeInfo = intakeData.nutrients[nutrientName];
      const intake = intakeInfo?.intake ?? 0;
  
      if (standard === 0) {
        result[nutrientName] = 0;
      } else {
        const achievementPercentage = (intake / standard) * 100;
        result[nutrientName] = Math.min(Math.max(achievementPercentage, 0), 100);
      }
    }
  
    userData.age;
    userData.gender;
    userData.activityLevel;
  
    return result;
  }
  return { calculateNutrientAchievementScores };
})();
export const calculateNutrientAchievementScores = __aivicBundle_144_calculateNutrientAchievementScores.calculateNutrientAchievementScores;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateNutrientAchievementScores */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutritionGap exports=calculateNutritionGap */
const __aivicBundle_145_calculateNutritionGap = (() => {
  interface CalculateNutritionGapInput {
    nutritionItemId: string;
    nutritionItemName: string;
    targetValue: number;
    currentValue: number;
    unit: string;
    precision: number;
  }
  
  interface CalculateNutritionGapResult {
    gap: number;
    gapPercentage: number;
    isPositive: boolean;
  }
  
   function calculateNutritionGap(
    input: CalculateNutritionGapInput
  ): CalculateNutritionGapResult {
    const { targetValue, currentValue, precision } = input;
  
    if (targetValue < 0 || currentValue < 0) {
      throw new Error("栄養値は0以上である必要があります");
    }
  
    if (currentValue > targetValue) {
      throw new Error("目標値より現在値が高い場合は処理できません");
    }
  
    const gap = targetValue - currentValue;
    const gapPercentage =
      targetValue === 0 ? 0 : Math.round((gap / targetValue) * 100);
    const isPositive = gap > 0;
  
    return {
      gap: Number(gap.toFixed(precision)),
      gapPercentage,
      isPositive,
    };
  }
  return { calculateNutritionGap };
})();
export const calculateNutritionGap = __aivicBundle_145_calculateNutritionGap.calculateNutritionGap;
