/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateNutritionLogic exports=evaluateNutritionLogic */
const __aivicBundle_147_evaluateNutritionLogic = (() => {
  interface EvaluateNutritionLogicInput {
    nutrient_id: number;
    nutrient_name: string;
    target_value: number;
    actual_value: number;
    achievement_rate: number;
  }
  
  interface EvaluateNutritionLogicItem {
    nutrient_id: number;
    nutrient_name: string;
    achievement_rate: number;
    is_passed: boolean;
    judgement: "合格" | "不合格";
    priority_rank: number;
    improvement_gap?: number;
  }
  
  interface EvaluateNutritionLogicResult {
    items: EvaluateNutritionLogicItem[];
    overall_judgement: "合格" | "不合格";
    failed_count: number;
    passed_count: number;
    failure_rate: number;
  }
  
   function evaluateNutritionLogic(
    nutritionData: EvaluateNutritionLogicInput[]
  ): EvaluateNutritionLogicResult {
    if (!nutritionData || nutritionData.length === 0) {
      throw new Error("栄養データが提供されていません");
    }
  
    for (const item of nutritionData) {
      if (item.achievement_rate < 0 || item.achievement_rate > 100) {
        throw new Error("達成度スコアが無効な範囲です（0～100の範囲内である必要があります）");
      }
    }
  
    const PASS_THRESHOLD = 50;
  
    const itemsWithGap = nutritionData.map((item) => {
      const is_passed = item.achievement_rate >= PASS_THRESHOLD;
      const improvement_gap = Math.max(0, item.target_value - item.actual_value);
  
      return {
        nutrient_id: item.nutrient_id,
        nutrient_name: item.nutrient_name,
        achievement_rate: item.achievement_rate,
        is_passed,
        judgement: is_passed ? ("合格" as const) : ("不合格" as const),
        improvement_gap,
      };
    });
  
    const failedItems = itemsWithGap.filter((item) => !item.is_passed);
    const passedItems = itemsWithGap.filter((item) => item.is_passed);
  
    failedItems.sort((a, b) => a.achievement_rate - b.achievement_rate);
  
    const itemsWithPriority = itemsWithGap.map((item, index) => {
      if (item.is_passed) {
        return {
          ...item,
          priority_rank: 0,
        };
      }
  
      const failedIndex = failedItems.findIndex(
        (f) => f.nutrient_id === item.nutrient_id
      );
      return {
        ...item,
        priority_rank: failedIndex + 1,
      };
    });
  
    const failed_count = failedItems.length;
    const passed_count = passedItems.length;
    const total_count = itemsWithPriority.length;
    const failure_rate =
      total_count > 0 ? Math.round((failed_count / total_count) * 100) : 0;
  
    const overall_judgement =
      failed_count > 0 ? ("不合格" as const) : ("合格" as const);
  
    return {
      items: itemsWithPriority,
      overall_judgement,
      failed_count,
      passed_count,
      failure_rate,
    };
  }
  return { evaluateNutritionLogic };
})();
export const evaluateNutritionLogic = __aivicBundle_147_evaluateNutritionLogic.evaluateNutritionLogic;
/* AIVIC_FUNCTION_BUNDLE_END owner=evaluateNutritionLogic */

