const __aivicBundle_149_validateNutritionIntakeData = (() => {
  function validateNutritionIntakeData(
    input: any
  ): { isValid: boolean; validationResults: NutritionValidationData[]; errorCount: number } {
    // Handle both array and single object inputs
    const dataArray = Array.isArray(input) ? input : [input];
    
    const validationResults: NutritionValidationData[] = [];
    let errorCount = 0;
  
    for (const item of dataArray) {
      const nutrientId = item.nutrientId || '';
      const nutrientName = item.nutrientName || '';
      const intakeAmount = item.intakeAmount !== undefined ? item.intakeAmount : item.actualValue;
      const unit = item.unit || '';
      
  
      let isValid = true;
      let errorMessage: string | undefined;
  
      // Validate intake amount is not negative
      if (intakeAmount < 0) {
        isValid = false;
        errorMessage = '摂取量は負の値であってはいけません';
        errorCount++;
      }
  
      // Validate intake amount is a number
      if (typeof intakeAmount !== 'number' || isNaN(intakeAmount)) {
        isValid = false;
        errorMessage = '摂取量は有効な数値である必要があります';
        errorCount++;
      }
  
      // Validate nutrient name exists
      if (!nutrientName || nutrientName.trim() === '') {
        isValid = false;
        errorMessage = '栄養素名は必須です';
        errorCount++;
      }
  
      // Validate unit exists
      if (!unit || unit.trim() === '') {
        isValid = false;
        errorMessage = '単位は必須です';
        errorCount++;
      }
  
      const validationResult: NutritionValidationData = {
        nutrientId,
        nutrientName,
        targetValue: 0,
        actualValue: intakeAmount,
        unit,
        achievementRate: 0,
        isValid,
        errorMessage
      };
  
      validationResults.push(validationResult);
    }
  
    return {
      isValid: errorCount === 0,
      validationResults,
      errorCount
    };
  }
  return { validateNutritionIntakeData };
})();
