const __aivicBundle_150_prioritizeNutritionItemsByAchievementRate = (() => {
  function prioritizeNutritionItemsByAchievementRate(
    nutritionItems: Array<{
      nutrient_id?: string;
      nutrient_name?: string;
      target_value: number;
      actual_value: number;
      unit?: string;
      achievement_rate?: number;
    }>
  ): Array<{
    nutrient_id?: string;
    nutrient_name?: string;
    target_value: number;
    actual_value: number;
    unit?: string;
    achievement_rate: number;
    priority: number;
    gap_to_target: number;
  }> {
    if (!Array.isArray(nutritionItems) || nutritionItems.length === 0) {
      return [];
    }
  
    const itemsWithGap = nutritionItems.map((item) => {
      const achievementRate =
        item.achievement_rate !== undefined
          ? item.achievement_rate
          : item.target_value > 0
            ? Math.round((item.actual_value / item.target_value) * 100)
            : 0;
  
      const gapToTarget = item.target_value - item.actual_value;
  
      return {
        nutrient_id: item.nutrient_id,
        nutrient_name: item.nutrient_name,
        target_value: item.target_value,
        actual_value: item.actual_value,
        unit: item.unit,
        achievement_rate: achievementRate,
        gap_to_target: gapToTarget,
      };
    });
  
    const sorted = itemsWithGap.sort(
      (a, b) => a.achievement_rate - b.achievement_rate
    );
  
    const prioritized = sorted.map((item, index) => ({
      ...item,
      priority: index + 1,
    }));
  
    return prioritized;
  }
  return { prioritizeNutritionItemsByAchievementRate };
})();
