const __aivicBundle_151_calculateNutritionPriorityOrder = (() => {
  interface NutritionItemWithPriority {
    nutritionItemId: string;
    name: string;
    targetValue?: number;
    actualValue?: number;
    achievementRate: number;
    importanceScore: number;
    registrationOrder: number;
    priorityRank: number;
  }
  
   function calculateNutritionPriorityOrder(
    nutritionItems: any[]
  ): NutritionItemWithPriority[] {
    if (!nutritionItems || nutritionItems.length === 0) {
      return [];
    }
  
    const itemsWithScores = nutritionItems.map((item) => ({
      ...item,
      priorityScore:
        (100 - item.achievementRate) * 0.6 + item.importanceScore * 10 * 0.4,
    }));
  
    const sorted = itemsWithScores.sort((a, b) => {
      const achievementDiff = a.achievementRate - b.achievementRate;
      if (achievementDiff !== 0) {
        return achievementDiff;
      }
  
      const importanceDiff = b.importanceScore - a.importanceScore;
      if (importanceDiff !== 0) {
        return importanceDiff;
      }
  
      return a.registrationOrder - b.registrationOrder;
    });
  
    const result: NutritionItemWithPriority[] = sorted.map((item, index) => ({
      nutritionItemId: item.nutritionItemId,
      name: item.name,
      achievementRate: item.achievementRate,
      importanceScore: item.importanceScore,
      registrationOrder: item.registrationOrder,
      priorityRank: index + 1,
    }));
  
    return result;
  }
  return { calculateNutritionPriorityOrder };
})();
