/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutritionPriority exports=calculateNutritionPriority */
const __aivicBundle_152_calculateNutritionPriority = (() => {
  function calculateNutritionPriority(
    nutritionData: Array<{
      item_id: string;
      target_value: number;
      actual_value: number;
    }> | null | undefined
  ): {
    priorities: Array<{
      item_id: string;
      achievement_rate: number;
      gap: number;
      priority_rank: number;
    }>;
    total_items: number;
    critical_items_count: number;
  } {
    if (!nutritionData || nutritionData === null || nutritionData === undefined) {
      throw new Error("栄養項目データが提供されていません");
    }
  
    if (Array.isArray(nutritionData) && nutritionData.length === 0) {
      throw new Error("栄養項目データが空です");
    }
  
    const priorities = nutritionData.map((item) => {
      const achievementRate = (item.actual_value / item.target_value) * 100;
      const gap = item.target_value - item.actual_value;
      const priorityScore = Math.max(0, Math.min(100, gap / item.target_value * 100));
  
      return {
        item_id: item.item_id,
        achievement_rate: achievementRate,
        gap: gap,
        priority_score: priorityScore,
      };
    });
  
    const sortedPriorities = priorities
      .sort((a, b) => b.priority_score - a.priority_score)
      .map((p, index) => ({
        ...p,
        priority_rank: index + 1,
      }));
  
    const criticalItemsCount = sortedPriorities.filter(
      (p) => p.priority_score >= 70
    ).length;
  
    return {
      priorities: sortedPriorities.map((p) => ({
        item_id: p.item_id,
        achievement_rate: p.achievement_rate,
        gap: p.gap,
        priority_rank: p.priority_rank,
      })),
      total_items: nutritionData.length,
      critical_items_count: criticalItemsCount,
    };
  }
  return { calculateNutritionPriority };
})();
