/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutrientDeviationQuantification exports=calculateNutrientDeviationQuantification */
const __aivicBundle_154_calculateNutrientDeviationQuantification = (() => {
  function calculateNutrientDeviationQuantification(input: any): any {
    // Validate input structure
    if (!input || typeof input !== 'object') {
      throw new Error('入力データが無効です');
    }
  
    const { userId, recordDate, nutritionItems } = input;
  
    // Validate nutritionItems exists and is an array
    if (!Array.isArray(nutritionItems)) {
      throw new Error('栄養項目リストが無効です');
    }
  
    // Validate nutritionItems is not empty
    if (nutritionItems.length === 0) {
      throw new Error('栄養項目リストが空です');
    }
  
    // Validate all items have targetValue defined and > 0
    for (const item of nutritionItems) {
      if (item.targetValue === null || item.targetValue === undefined) {
        throw new Error('目標値が定義されていません');
      }
      if (typeof item.targetValue !== 'number' || item.targetValue <= 0) {
        throw new Error('目標値は0より大きい数値である必要があります');
      }
    }
  
    // Calculate deviation data for each nutrient
    const deviationData = nutritionItems.map((item: any) => {
      const actualIntake = item.actualIntake || 0;
      const targetValue = item.targetValue;
      const achievementRate = (actualIntake / targetValue) * 100;
      const deviation = actualIntake - targetValue;
      const deviationType = deviation < 0 ? '不足' : deviation > 0 ? '超過' : 'バランス';
  
      return {
        nutrientId: item.nutrientId,
        nutrientName: item.nutrientName,
        targetValue: targetValue,
        actualIntake: actualIntake,
        achievementRate: Math.round(achievementRate * 100) / 100,
        deviation: deviation,
        status: deviationType,
      };
    });
  
    // Calculate overall achievement rate
    const overallAchievementRate =
      Math.round(
        (deviationData.reduce((sum: number, d: any) => sum + d.achievementRate, 0) /
          deviationData.length) *
          100
      ) / 100;
  
    // Create priority ranking based on improvement gap
    const priorityRanking = deviationData
      .map((d: any, index: number) => ({
        nutrientId: d.nutrientId,
        nutrientName: d.nutrientName,
        improvementGap: d.status === '不足' ? Math.abs(d.deviation) : 0,
        priority: index + 1,
      }))
      .sort((a: any, b: any) => b.improvementGap - a.improvementGap)
      .map((item: any, index: number) => ({
        ...item,
        priority: index + 1,
      }));
  
    return {
      userId: userId,
      recordDate: recordDate,
      deviationData: deviationData,
      overallAchievementRate: overallAchievementRate,
      priorityRanking: priorityRanking,
    };
  }
  return { calculateNutrientDeviationQuantification };
})();
