/* AIVIC_FUNCTION_BUNDLE_START owner=verifyNutritionStandardImprovementEffect exports=verifyNutritionStandardImprovementEffect */
const __aivicBundle_158_verifyNutritionStandardImprovementEffect = (() => {
  function verifyNutritionStandardImprovementEffect(input: {
    userId: string | null;
    deploymentDate: Date | null;
    mealRecords: Array<{
      recordId: string;
      userId: string;
      mealDate: Date;
      nutritionData: Record<string, number>;
    }> | null;
  }): {
    status: 'success' | 'skipped';
    reason?: string;
    userId: string;
    verificationExecuted: boolean;
    improvedEffectScores: Array<{
      nutrientName: string;
      achievementRate: number;
    }>;
    errorMessage: null | string;
  } {
    if (!input.userId) {
      throw new Error('ユーザーIDが指定されていません');
    }
  
    if (!input.deploymentDate) {
      throw new Error('デプロイ日が指定されていません');
    }
  
    const mealRecords = input.mealRecords ?? [];
  
    if (mealRecords.length === 0) {
      return {
        status: 'skipped',
        reason: '食事記録がありません',
        userId: input.userId,
        verificationExecuted: false,
        improvedEffectScores: [],
        errorMessage: null,
      };
    }
  
    const deploymentDate = new Date(input.deploymentDate);
    const postDeploymentRecords = mealRecords.filter((record) => {
      const recordDate = new Date(record.mealDate);
      return recordDate >= deploymentDate;
    });
  
    if (postDeploymentRecords.length === 0) {
      return {
        status: 'skipped',
        reason: 'デプロイ後7日以上の食事記録が必要です',
        userId: input.userId,
        verificationExecuted: false,
        improvedEffectScores: [],
        errorMessage: null,
      };
    }
  
    const oldestPostDeploymentDate = new Date(
      Math.min(...postDeploymentRecords.map((r) => new Date(r.mealDate).getTime()))
    );
    const latestPostDeploymentDate = new Date(
      Math.max(...postDeploymentRecords.map((r) => new Date(r.mealDate).getTime()))
    );
  
    const daysDifference = Math.floor(
      (latestPostDeploymentDate.getTime() - oldestPostDeploymentDate.getTime()) /
        (1000 * 60 * 60 * 24)
    );
  
    if (daysDifference < 7) {
      return {
        status: 'skipped',
        reason: 'デプロイ後7日以上の食事記録が必要です',
        userId: input.userId,
        verificationExecuted: false,
        improvedEffectScores: [],
        errorMessage: null,
      };
    }
  
    const nutrientAggregates: Record<string, { total: number; count: number }> =
      {};
  
    for (const record of postDeploymentRecords) {
      if (record.nutritionData) {
        for (const [nutrientName, value] of Object.entries(
          record.nutritionData
        )) {
          if (typeof value === 'number') {
            if (!nutrientAggregates[nutrientName]) {
              nutrientAggregates[nutrientName] = { total: 0, count: 0 };
            }
            nutrientAggregates[nutrientName].total += value;
            nutrientAggregates[nutrientName].count += 1;
          }
        }
      }
    }
  
    const improvedEffectScores = Object.entries(nutrientAggregates).map(
      ([nutrientName, aggregate]) => {
        const averageValue = aggregate.total / aggregate.count;
        const achievementRate = Math.min(
          100,
          Math.max(0, (averageValue / 100) * 100)
        );
  
        return {
          nutrientName,
          achievementRate,
        };
      }
    );
  
    return {
      status: 'success',
      userId: input.userId,
      verificationExecuted: true,
      improvedEffectScores,
      errorMessage: null,
    };
  }
  return { verifyNutritionStandardImprovementEffect };
})();
export const verifyNutritionStandardImprovementEffect = __aivicBundle_158_verifyNutritionStandardImprovementEffect.verifyNutritionStandardImprovementEffect;
/* AIVIC_FUNCTION_BUNDLE_END owner=verifyNutritionStandardImprovementEffect */

