const __aivicBundle_159_calculateNutritionAchievementComparison = (() => {
  function calculateNutritionAchievementComparison(
    input: any,
    postImprovementData?: any,
    nutritionStandards?: any,
    selectedNutrients?: any
  ): any {
    // 4引数パターン: preImprovementData, postImprovementData, nutritionStandards, selectedNutrients
    if (
      Array.isArray(input) &&
      Array.isArray(postImprovementData) &&
      nutritionStandards &&
      Array.isArray(selectedNutrients)
    ) {
      return calculateComparisonFromArrays(
        input,
        postImprovementData,
        nutritionStandards,
        selectedNutrients
      );
    }
  
    // 1引数パターン: { before_achievement_rates, after_achievement_rates }
    if (
      input &&
      typeof input === "object" &&
      !Array.isArray(input) &&
      input.before_achievement_rates &&
      input.after_achievement_rates
    ) {
      return calculateComparisonFromRates(
        input.before_achievement_rates,
        input.after_achievement_rates
      );
    }
  
    throw new Error("Invalid input format for calculateNutritionAchievementComparison");
  }
  
  function calculateComparisonFromRates(
    beforeRates: Record<string, number>,
    afterRates: Record<string, number>
  ): any {
    const correctedAfterRates: Record<string, number> = {};
    const correctedItems: string[] = [];
  
    // 100%を超える値を補正
    for (const [key, value] of Object.entries(afterRates)) {
      if (value > 100) {
        correctedAfterRates[key] = 100;
        correctedItems.push(key);
      } else {
        correctedAfterRates[key] = value;
      }
    }
  
    // 改善ギャップを計算
    const improvementGap: Record<string, number> = {};
    for (const key of Object.keys(beforeRates)) {
      improvementGap[key] = correctedAfterRates[key] - beforeRates[key];
    }
  
    const hasCorrection = correctedItems.length > 0;
    const warningMessage = hasCorrection
      ? `補正が適用されました。以下の項目が100%に調整されました: ${correctedItems.join(", ")}`
      : "";
  
    return {
      after_achievement_rates_corrected: correctedAfterRates,
      before_achievement_rates: beforeRates,
      has_correction: hasCorrection,
      corrected_items: correctedItems,
      improvement_gap: improvementGap,
      warning_message: warningMessage,
      correction_applied_indicator: hasCorrection,
    };
  }
  
  function calculateComparisonFromArrays(
    preImprovementData: Array<Record<string, any>>,
    postImprovementData: Array<Record<string, any>>,
    nutritionStandards: Record<string, number>,
    selectedNutrients: string[]
  ): any {
    // 各栄養項目の平均値を計算
    const preAverages: Record<string, number> = {};
    const postAverages: Record<string, number> = {};
  
    for (const nutrient of selectedNutrients) {
      const preValues = preImprovementData.map((d) => d[nutrient]).filter((v) => v !== undefined);
      const postValues = postImprovementData.map((d) => d[nutrient]).filter((v) => v !== undefined);
  
      preAverages[nutrient] = preValues.length > 0 ? preValues.reduce((a, b) => a + b, 0) / preValues.length : 0;
      postAverages[nutrient] = postValues.length > 0 ? postValues.reduce((a, b) => a + b, 0) / postValues.length : 0;
    }
  
    // 達成度を計算
    const preImprovement: Record<string, any> = {};
    const postImprovement: Record<string, any> = {};
    const effectDifference: Record<string, any> = {};
    const comparisonData: Array<any> = [];
  
    for (const nutrient of selectedNutrients) {
      const preAchievementPercentage = (preAverages[nutrient] / nutritionStandards[nutrient]) * 100;
      const postAchievementPercentage = (postAverages[nutrient] / nutritionStandards[nutrient]) * 100;
  
      preImprovement[nutrient] = {
        achievementPercentage: Math.round(preAchievementPercentage * 10) / 10,
        averageIntake: Math.round(preAverages[nutrient] * 10) / 10,
      };
  
      postImprovement[nutrient] = {
        achievementPercentage: Math.round(postAchievementPercentage * 10) / 10,
        averageIntake: Math.round(postAverages[nutrient] * 10) / 10,
      };
  
      const absoluteDifference = postAchievementPercentage - preAchievementPercentage;
      const percentageDifference = preAchievementPercentage !== 0
        ? (absoluteDifference / preAchievementPercentage) * 100
        : 0;
  
      effectDifference[nutrient] = {
        absoluteDifference: Math.round(absoluteDifference * 10) / 10,
        percentageDifference: Math.round(percentageDifference * 10) / 10,
      };
  
      comparisonData.push({
        nutrient,
        preAchievementPercentage: Math.round(preAchievementPercentage * 10) / 10,
        postAchievementPercentage: Math.round(postAchievementPercentage * 10) / 10,
        effectDifference: Math.round(absoluteDifference * 10) / 10,
        effectPercentageChange: Math.round(percentageDifference * 10) / 10,
      });
    }
  
    // グラフデータを生成
    const graphData = {
      labels: selectedNutrients,
      preImprovementDataset: selectedNutrients.map(
        (n) => Math.round((preAverages[n] / nutritionStandards[n]) * 100 * 10) / 10
      ),
      postImprovementDataset: selectedNutrients.map(
        (n) => Math.round((postAverages[n] / nutritionStandards[n]) * 100 * 10) / 10
      ),
    };
  
    // テーブルデータを生成
    const tableData = selectedNutrients.map((nutrient) => ({
      nutrient,
      preAchievementPercentage: preImprovement[nutrient].achievementPercentage,
      postAchievementPercentage: postImprovement[nutrient].achievementPercentage,
      absoluteDifference: effectDifference[nutrient].absoluteDifference,
      percentageDifference: effectDifference[nutrient].percentageDifference,
    }));
  
    return {
      preImprovement,
      postImprovement,
      effectDifference,
      comparisonData,
      graphData,
      tableData,
    };
  }
  return { calculateNutritionAchievementComparison };
})();
export const calculateNutritionAchievementComparison: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_159_calculateNutritionAchievementComparison.calculateNutritionAchievementComparison as (...args: any[]) => any)(...args);
