/* AIVIC_FUNCTION_BUNDLE_START owner=filterAnomalousAndMissingValues exports=filterAnomalousAndMissingValues */
const __aivicBundle_172_filterAnomalousAndMissingValues = (() => {
  function filterAnomalousAndMissingValues(input: any): any {
    // Handle empty dataset
    if (!Array.isArray(input) || input.length === 0) {
      return {
        filtered_data: [],
        excluded_count: 0,
        error_log: [],
        user_error_message: '',
        status: 'completed_successfully',
        excluded_records_detail: [],
        error_log_timestamp: new Date().toISOString(),
      };
    }
  
    const filtered_data: any[] = [];
    const excluded_records_detail: any[] = [];
    const error_log: string[] = [];
    let anomalousCount = 0;
    let missingCount = 0;
  
    // Validate each record
    for (const record of input) {
      const recordErrors: string[] = [];
      let isValid = true;
  
      // Check for null/undefined user_id
      if (record.user_id === null || record.user_id === undefined) {
        recordErrors.push('user_id: null または undefined');
        isValid = false;
      }
  
      // Check for invalid date format
      if (typeof record.date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(record.date)) {
        recordErrors.push('date: 不正な日付形式');
        isValid = false;
      }
  
      // Check numeric fields
      const numericFields = ['calorie_intake', 'protein_intake', 'fat_intake', 'carbohydrate_intake'];
      for (const field of numericFields) {
        const value = record[field];
  
        // Check for non-numeric types (string, object, array, etc.)
        if (typeof value === 'string') {
          recordErrors.push(`${field}: データ型エラー（文字列が入力されました）`);
          isValid = false;
          error_log.push(`${field}: データ型エラー`);
        } else if (value === null) {
          recordErrors.push(`${field}: null`);
          isValid = false;
          error_log.push(`${field}: null`);
          missingCount++;
        } else if (value === undefined) {
          recordErrors.push(`${field}: undefined`);
          isValid = false;
          error_log.push(`${field}: undefined`);
          missingCount++;
        } else if (typeof value === 'object' || Array.isArray(value)) {
          recordErrors.push(`${field}: データ型エラー（オブジェクト/配列が入力されました）`);
          isValid = false;
          error_log.push(`${field}: データ型エラー`);
        } else if (typeof value !== 'number') {
          recordErrors.push(`${field}: データ型エラー`);
          isValid = false;
          error_log.push(`${field}: データ型エラー`);
        }
      }
  
      if (isValid) {
        filtered_data.push(record);
      } else {
        anomalousCount++;
        excluded_records_detail.push({
          user_id: record.user_id,
          reason: recordErrors.join(', '),
        });
      }
    }
  
    // Check if completely invalid dataset (all records excluded)
    if (filtered_data.length === 0 && excluded_records_detail.length > 0) {
      throw new Error('データ型エラー: すべてのレコードが不正なデータ型を含んでいます');
    }
  
    const excluded_count = input.length - filtered_data.length;
    const hasErrors = error_log.length > 0;
    const status = hasErrors ? 'completed_with_errors' : 'completed_successfully';
    const user_error_message = hasErrors ? '不正なデータが検出されました。詳細はエラーログを確認してください。' : '';
  
    return {
      filtered_data,
      excluded_count,
      error_log,
      user_error_message,
      status,
      excluded_records_detail,
      error_log_timestamp: new Date().toISOString(),
    };
  }
  return { filterAnomalousAndMissingValues };
})();
export const filterAnomalousAndMissingValues = __aivicBundle_172_filterAnomalousAndMissingValues.filterAnomalousAndMissingValues;
/* AIVIC_FUNCTION_BUNDLE_END owner=filterAnomalousAndMissingValues */

