/* AIVIC_FUNCTION_BUNDLE_START owner=detectSLAExceeded exports=detectSLAExceeded */
const __aivicBundle_175_detectSLAExceeded = (() => {
  interface DetectSLAExceededInput {
    requestTimestamp: string;
    currentTimestamp: string;
    slaThresholdMs: number;
  }
  
  interface DetectSLAExceededResult {
    slaCheckId: string;
    isExceeded: boolean;
    elapsedMs: number;
    excessMs: number;
    detectedAt: string;
  }
  
   function detectSLAExceeded(
    input: DetectSLAExceededInput
  ): DetectSLAExceededResult {
    const { requestTimestamp, currentTimestamp, slaThresholdMs } = input;
  
    // Validate timestamps
    const requestTime = new Date(requestTimestamp);
    const currentTime = new Date(currentTimestamp);
  
    if (isNaN(requestTime.getTime())) {
      throw new Error("不正なタイムスタンプ: requestTimestamp");
    }
    if (isNaN(currentTime.getTime())) {
      throw new Error("不正なタイムスタンプ: currentTimestamp");
    }
  
    // Validate SLA threshold
    if (slaThresholdMs < 0) {
      throw new Error("SLA閾値は0以上である必要があります");
    }
  
    // Calculate elapsed time in milliseconds
    const elapsedMs = currentTime.getTime() - requestTime.getTime();
  
    // Determine if SLA is exceeded
    const isExceeded = elapsedMs > slaThresholdMs;
  
    // Calculate excess time (negative if within SLA)
    const excessMs = Math.max(0, elapsedMs - slaThresholdMs);
  
    return {
      slaCheckId: randomUUID(),
      isExceeded,
      elapsedMs,
      excessMs,
      detectedAt: currentTimestamp,
    };
  }
  return { detectSLAExceeded };
})();
export const detectSLAExceeded = __aivicBundle_175_detectSLAExceeded.detectSLAExceeded;
