/* AIVIC_FUNCTION_BUNDLE_START owner=detectShoppingListSLADelay exports=detectShoppingListSLADelay */
const __aivicBundle_177_detectShoppingListSLADelay = (() => {
  function detectShoppingListSLADelay(input: {
    userId: string;
    generationStartTime: Date;
    slaThresholdMs: number;
    nutritionValidationResult: { pass: boolean; achievementRate: number };
    shoppingListItems: Array<{ itemId: string; name: string; quantity: number; unit: string }>;
    elapsedTimeCalculator?: { getElapsedMs: () => number };
  }): {
    delayDetectionId: string;
    isDelayed: boolean;
    delayMinutes: number;
    delayPercentageOfSLA: number;
    estimatedCompletionTime: string;
    alertLevel: "on_track" | "warning" | "critical";
    delayReason: string;
    detectionTimestamp: string;
  } {
    const {
      userId,
      generationStartTime,
      slaThresholdMs,
      nutritionValidationResult,
      shoppingListItems,
      elapsedTimeCalculator,
    } = input;
  
    if (!userId || !userId.trim()) {
      throw new Error("userId is required");
    }
  
    if (!nutritionValidationResult || typeof nutritionValidationResult.pass !== "boolean") {
      throw new Error("nutritionValidationResult is required and must have pass property");
    }
  
    if (!Array.isArray(shoppingListItems)) {
      throw new Error("shoppingListItems must be an array");
    }
  
    const detectionTimestamp = new Date().toISOString();
    const delayDetectionId = randomUUID();
  
    let elapsedMs: number;
  
    if (elapsedTimeCalculator && typeof elapsedTimeCalculator.getElapsedMs === "function") {
      elapsedMs = elapsedTimeCalculator.getElapsedMs();
    } else {
      const startTime =
        generationStartTime instanceof Date
          ? generationStartTime.getTime()
          : new Date(generationStartTime).getTime();
      const currentTime = new Date().getTime();
      elapsedMs = currentTime - startTime;
    }
  
    const isDelayed = elapsedMs > slaThresholdMs;
    const delayMs = Math.max(0, elapsedMs - slaThresholdMs);
    const delayMinutes = Math.ceil(delayMs / 60000);
    const delayPercentageOfSLA = Math.round((elapsedMs / slaThresholdMs) * 100);
  
    const estimatedCompletionMs = elapsedMs + (slaThresholdMs - elapsedMs) * 0.5;
    const estimatedCompletionTime = new Date(
      new Date().getTime() + (estimatedCompletionMs - elapsedMs)
    ).toISOString();
  
    let alertLevel: "on_track" | "warning" | "critical";
    let delayReason: string;
  
    if (!isDelayed) {
      alertLevel = "on_track";
      delayReason = "";
    } else if (delayPercentageOfSLA <= 150) {
      alertLevel = "warning";
      delayReason = "献立計画の処理時間が予定を超過しています";
    } else {
      alertLevel = "critical";
      delayReason = "複雑な献立計画による処理時間超過";
    }
  
    return {
      delayDetectionId,
      isDelayed,
      delayMinutes,
      delayPercentageOfSLA,
      estimatedCompletionTime,
      alertLevel,
      delayReason,
      detectionTimestamp,
    };
  }
  return { detectShoppingListSLADelay };
})();
