/* AIVIC_FUNCTION_BUNDLE_END owner=detectShoppingListSLADelay */

/* AIVIC_FUNCTION_BUNDLE_START owner=detectShoppingListGenerationSLADelay exports=detectShoppingListGenerationSLADelay */
const __aivicBundle_178_detectShoppingListGenerationSLADelay = (() => {
  interface DetectShoppingListGenerationSLADelayInput {
    processStartTime: number;
    currentTime: number;
    slaThresholdMs: number;
    processId: string;
  }
  
  interface SLADelayLogEntry {
    timestamp: number;
    processId: string;
    delayDetected: boolean;
    elapsedMs: number;
    slaThresholdMs: number;
  }
  
  interface DetectShoppingListGenerationSLADelayResult {
    isDelayed: boolean;
    shouldExecuteFallback: boolean;
    elapsedTimeMs: number;
    status: string;
    logEntry: SLADelayLogEntry;
  }
  
   function detectShoppingListGenerationSLADelay(
    input: DetectShoppingListGenerationSLADelayInput
  ): DetectShoppingListGenerationSLADelayResult {
    const { processStartTime, currentTime, slaThresholdMs, processId } = input;
  
    // Validation: SLA threshold must be positive
    if (slaThresholdMs <= 0) {
      throw new Error('SLA閾値は正の値である必要があります');
    }
  
    // Validation: current time must not be before start time
    if (currentTime < processStartTime) {
      throw new Error('現在時刻は開始時刻より前にすることはできません');
    }
  
    // Calculate elapsed time
    const elapsedTimeMs = currentTime - processStartTime;
  
    // Determine if delay is detected
    const isDelayed = elapsedTimeMs >= slaThresholdMs;
  
    // Create log entry
    const logEntry: SLADelayLogEntry = {
      timestamp: currentTime,
      processId,
      delayDetected: isDelayed,
      elapsedMs: elapsedTimeMs,
      slaThresholdMs,
    };
  
    // Determine status and fallback requirement
    const status = isDelayed ? 'delayed' : 'on_schedule';
    const shouldExecuteFallback = isDelayed;
  
    return {
      isDelayed,
      shouldExecuteFallback,
      elapsedTimeMs,
      status,
      logEntry,
    };
  }
  return { detectShoppingListGenerationSLADelay };
})();
