const __aivicBundle_188_calculateAlgorithmImprovementMetrics = (() => {
  interface CalculateAlgorithmImprovementMetricsInput {
    userSatisfactionScore?: number;
    mealGenerationSuccessRateImprovement?: number;
    cookingTimeReductionDegree?: number;
    weeklyComparison?: number;
    preImprovementMetrics?: {
      successRate: number;
      cookingTimeReduction: number;
      userSatisfactionScore: number;
      timestamp?: Date;
    } | null;
    postImprovementMetrics?: {
      successRate: number;
      cookingTimeReduction: number;
      userSatisfactionScore: number;
      timestamp?: Date;
    } | null;
  }
  
  interface CalculateAlgorithmImprovementMetricsOutput {
    improvementEffectScore?: number;
    successRateImprovement?: number;
    cookingTimeReductionImprovement?: number;
    userSatisfactionScoreImprovement?: number;
    overallImprovementScore?: number;
    errorOccurred: boolean;
    errorMessage: string | null;
  }
  
   function calculateAlgorithmImprovementMetrics(
    input: CalculateAlgorithmImprovementMetricsInput
  ): CalculateAlgorithmImprovementMetricsOutput {
    // Handle pre/post improvement metrics comparison mode
    if (
      input.preImprovementMetrics !== undefined ||
      input.postImprovementMetrics !== undefined
    ) {
      if (input.preImprovementMetrics === null && input.postImprovementMetrics === null) {
        return {
          errorOccurred: true,
          errorMessage: "改善前後データが不足しています",
        };
      }
  
      if (input.preImprovementMetrics === null) {
        return {
          errorOccurred: true,
          errorMessage: "改善前データが不足しています",
        };
      }
  
      if (input.postImprovementMetrics === null) {
        return {
          errorOccurred: true,
          errorMessage: "改善後データが不足しています",
        };
      }
  
      const pre = input.preImprovementMetrics;
      const post = input.postImprovementMetrics;
  
      // Calculate improvement percentages
      const successRateImprovement =
        pre.successRate !== 0
          ? Number((((post.successRate - pre.successRate) / pre.successRate) * 100).toFixed(2))
          : 0;
  
      const cookingTimeReductionImprovement =
        pre.cookingTimeReduction !== 0
          ? Number((((post.cookingTimeReduction - pre.cookingTimeReduction) / pre.cookingTimeReduction) * 100).toFixed(2))
          : 0;
  
      const userSatisfactionScoreImprovement =
        pre.userSatisfactionScore !== 0
          ? Number((((post.userSatisfactionScore - pre.userSatisfactionScore) / pre.userSatisfactionScore) * 100).toFixed(2))
          : 0;
  
      const overallImprovementScore = Number(
        (
          (successRateImprovement +
            cookingTimeReductionImprovement +
            userSatisfactionScoreImprovement) /
          3
        ).toFixed(2)
      );
  
      return {
        successRateImprovement,
        cookingTimeReductionImprovement,
        userSatisfactionScoreImprovement,
        overallImprovementScore,
        errorOccurred: false,
        errorMessage: null,
      };
    }
  
    // Handle boundary value mode with satisfaction score
    const userSatisfactionScore = input.userSatisfactionScore ?? 0;
    const mealGenerationSuccessRateImprovement =
      input.mealGenerationSuccessRateImprovement ?? 0;
    const cookingTimeReductionDegree = input.cookingTimeReductionDegree ?? 0;
    const weeklyComparison = input.weeklyComparison ?? 1;
  
    // Formula: (successRate * 0.4 + cookingTime * 0.35 + (weeklyComparison - 1) * 10 * 0.25) * (satisfaction / 100)
    const baseScore =
      mealGenerationSuccessRateImprovement * 0.4 +
      cookingTimeReductionDegree * 0.35 +
      (weeklyComparison - 1) * 10 * 0.25;
  
    const improvementEffectScore = Number(
      (baseScore * (userSatisfactionScore / 100)).toFixed(2)
    );
  
    return {
      improvementEffectScore,
      errorOccurred: false,
      errorMessage: null,
    };
  }
  return { calculateAlgorithmImprovementMetrics };
})();
export const calculateAlgorithmImprovementMetrics = __aivicBundle_188_calculateAlgorithmImprovementMetrics.calculateAlgorithmImprovementMetrics;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateAlgorithmImprovementMetrics */

