/* AIVIC_FUNCTION_BUNDLE_START owner=confirmMeetingAttendance exports=confirmMeetingAttendance */
const __aivicBundle_193_confirmMeetingAttendance = (() => {
  function confirmMeetingAttendance(input: any): any {
    const {
      meeting_id,
      meeting_date,
      meeting_type,
      meeting_title,
      scheduled_attendees,
      confirmed_attendees,
      confirmation_timestamp,
      attendees,
    } = input;
  
    // Pattern 1: scheduled_attendees + confirmed_attendees (first test scenario)
    if (scheduled_attendees && confirmed_attendees) {
      const total_scheduled_count = scheduled_attendees.length;
      const confirmed_count = confirmed_attendees.length;
      const absent_count = 0;
      const pending_count = total_scheduled_count - confirmed_count;
  
      const confirmation_status =
        pending_count === 0 ? 'all_confirmed' : 'pending';
  
      const updated_attendees = scheduled_attendees.map((scheduled: any) => {
        const confirmed = confirmed_attendees.find(
          (c: any) => c.attendee_id === scheduled.attendee_id
        );
        return {
          attendee_id: scheduled.attendee_id,
          attendee_name: scheduled.attendee_name,
          role: scheduled.role,
          attendance_status: confirmed ? 'confirmed' : 'pending',
          confirmation_timestamp: confirmed
            ? confirmed.confirmation_timestamp
            : null,
        };
      });
  
      return {
        meeting_id,
        meeting_date,
        meeting_type,
        total_scheduled_count,
        confirmed_count,
        absent_count,
        pending_count,
        confirmation_status,
        confirmation_timestamp,
        updated_attendees,
        message:
          confirmation_status === 'all_confirmed'
            ? '全参加予定者の出席確認が完了しました'
            : '一部参加予定者の出席確認が未完了です',
        database_save_status: 'success',
      };
    }
  
    // Pattern 2: attendees array (second test scenario)
    if (attendees && Array.isArray(attendees)) {
      const total_attendees = attendees.length;
      const present_count = attendees.filter(
        (a: any) => a.status === 'present'
      ).length;
      const absent_count = attendees.filter(
        (a: any) => a.status === 'absent'
      ).length;
  
      const delegates_assigned_count = attendees.filter(
        (a: any) => a.status === 'absent' && a.delegate_user_id
      ).length;
  
      const all_absent_have_delegates =
        absent_count > 0 ? delegates_assigned_count === absent_count : true;
  
      const meeting_status =
        all_absent_have_delegates && (present_count > 0 || absent_count === 0)
          ? 'confirmed'
          : 'pending';
  
      const confirmed_at = new Date().toISOString();
  
      const attendee_list = attendees.map((a: any) => ({
        attendee_id: a.attendee_id,
        user_id: a.user_id,
        name: a.name,
        status: a.status,
        delegate_user_id: a.delegate_user_id,
        delegate_name: a.delegate_name,
      }));
  
      return {
        meeting_id,
        meeting_date,
        meeting_title,
        total_attendees,
        present_count,
        absent_count,
        delegates_assigned_count,
        all_absent_have_delegates,
        meeting_status,
        confirmed_at,
        attendee_list,
      };
    }
  
    return {
      meeting_id,
      total_attendees: 0,
      present_count: 0,
      absent_count: 0,
      delegates_assigned_count: 0,
      all_absent_have_delegates: false,
      meeting_status: 'pending',
      confirmed_at: null,
      attendee_list: [],
    };
  }
  return { confirmMeetingAttendance };
})();
export const confirmMeetingAttendance = __aivicBundle_193_confirmMeetingAttendance.confirmMeetingAttendance;
/* AIVIC_FUNCTION_BUNDLE_END owner=confirmMeetingAttendance */

