/* AIVIC_FUNCTION_BUNDLE_START owner=determineConferenceStatusWithAbsentees exports=determineConferenceStatusWithAbsentees */
const __aivicBundle_195_determineConferenceStatusWithAbsentees = (() => {
  function determineConferenceStatusWithAbsentees(input: {
    conferenceId: string;
    conferenceName: string;
    scheduledDateTime: Date;
    requiredAttendees: Array<{
      attendeeId: string;
      role: string;
      attendanceStatus: string;
      delegateId: string | null;
    }>;
    minRequiredAttendeeCount: number;
  }): {
    conferenceId: string;
    conferenceStatus: string;
    postponeReason: string;
    allRequiredAbsent: boolean;
    noDelegate: boolean;
    confirmedAttendeeCount: number;
    postponementTimestamp: string;
    canProceedWithConference: boolean;
    requiresRescheduling: boolean;
    totalRequiredAttendees: number;
    absentRequiredAttendees: number;
    availableDelegates: number;
    attendeeValidation: Array<{
      attendeeId: string;
      role: string;
      attendanceStatus: string;
      delegateId: string | null;
      delegatePresent: boolean;
    }>;
  } {
    if (!input.conferenceName || String(input.conferenceName).trim() === "") {
      throw new Error("conferenceName is required");
    }
    if (!input.scheduledDateTime) {
      throw new Error("scheduledDateTime is required");
    }
    if (input.minRequiredAttendeeCount === undefined || input.minRequiredAttendeeCount === null) {
      throw new Error("minRequiredAttendeeCount is required");
    }
  
    const {
      conferenceId,
      requiredAttendees,
    } = input;
  
    const totalRequiredAttendees = requiredAttendees.length;
    const absentAttendees = requiredAttendees.filter(
      (a) => a.attendanceStatus === "不在"
    );
    const absentRequiredAttendees = absentAttendees.length;
    const confirmedAttendeeCount = totalRequiredAttendees - absentRequiredAttendees;
  
    const attendeeValidation = requiredAttendees.map((attendee) => ({
      attendeeId: attendee.attendeeId,
      role: attendee.role,
      attendanceStatus: attendee.attendanceStatus,
      delegateId: attendee.delegateId,
      delegatePresent: attendee.delegateId !== null,
    }));
  
    const availableDelegates = requiredAttendees.filter(
      (a) => a.delegateId !== null
    ).length;
  
    const allRequiredAbsent = absentRequiredAttendees === totalRequiredAttendees;
    const noDelegate = availableDelegates === 0;
  
    let conferenceStatus: string;
    let postponeReason: string;
    let canProceedWithConference: boolean;
    let requiresRescheduling: boolean;
  
    if (allRequiredAbsent && noDelegate) {
      conferenceStatus = "延期";
      postponeReason = "必須参加者の全員不在及び代理者未指定";
      canProceedWithConference = false;
      requiresRescheduling = true;
    } else {
      conferenceStatus = "開催";
      postponeReason = "";
      canProceedWithConference = true;
      requiresRescheduling = false;
    }
  
    const postponementTimestamp = new Date().toISOString();
  
    return {
      conferenceId,
      conferenceStatus,
      postponeReason,
      allRequiredAbsent,
      noDelegate,
      confirmedAttendeeCount,
      postponementTimestamp,
      canProceedWithConference,
      requiresRescheduling,
      totalRequiredAttendees,
      absentRequiredAttendees,
      availableDelegates,
      attendeeValidation,
    };
  }
  return { determineConferenceStatusWithAbsentees };
})();
export const determineConferenceStatusWithAbsentees = __aivicBundle_195_determineConferenceStatusWithAbsentees.determineConferenceStatusWithAbsentees;
