const __aivicBundle_198_determineNextPriorityAfterImprovement = (() => {
  function determineNextPriorityAfterImprovement(input: {
    judgment_status: string;
    current_priority: number;
    improvement_delta: number;
  }): {
    next_priority: number;
    priority_adjusted: boolean;
    reason: string;
  } {
    if (input.judgment_status === 'No Improvement' || input.improvement_delta === 0) {
      return {
        next_priority: input.current_priority,
        priority_adjusted: false,
        reason: 'No Improvement detected - priority remains unchanged',
      };
    }
  
    const adjustedPriority = input.current_priority + input.improvement_delta;
  
    return {
      next_priority: adjustedPriority,
      priority_adjusted: true,
      reason: `Priority adjusted based on improvement delta of ${input.improvement_delta}`,
    };
  }
  return { determineNextPriorityAfterImprovement };
})();
