/* AIVIC_FUNCTION_BUNDLE_START owner=determineNextAlgorithmPriority exports=determineNextAlgorithmPriority */
const __aivicBundle_199_determineNextAlgorithmPriority = (() => {
  interface DetermineNextAlgorithmPriorityInput {
    metrics: {
      algorithmId: string;
      algorithmVersion: string;
      successRateBeforeImprovement: number;
      successRateAfterImprovement: number;
      successRateTargetThreshold: number;
      cookingTimeShorteningMinutes: number;
      cookingTimeTargetMinutes: number;
      userSatisfactionScoreBefore: number;
      userSatisfactionScoreAfter: number;
      userSatisfactionScoreTarget: number;
      improvementHistoryCount: number;
      evaluationMetricsCount: number;
      previousPriorityRank: number;
      analysisDate: string;
    };
    previousPriorityList: Array<{
      algorithmId: string;
      priorityRank: number;
      impactScore: number;
      implementationDifficulty: number;
    }>;
    improvementHistory: Array<{
      version: string;
      implementationDate: string;
      successRateAfter: number;
    }>;
  }
  
  interface NextPriorityItem {
    algorithmId: string;
    previousPriorityRank: number;
    newPriorityRank: number;
    newPriorityScore: number;
    impactScoreDelta: number;
  }
  
  interface DetermineNextAlgorithmPriorityResult {
    improvementSuccessJudgment: boolean;
    successRateImprovementPoints: number;
    cookingTimeTargetAchieved: boolean;
    userSatisfactionImprovement: number;
    overallImprovementScore: number;
    evidenceData: {
      improvementHistory: Array<{
        version: string;
        implementationDate: string;
        successRateAfter: number;
      }>;
      evaluationMetrics: {
        successRateChange: number;
        cookingTimeShorteningAchieved: number;
        userSatisfactionChange: number;
        metricsCollectionCount: number;
      };
      analysisTimestamp: string;
    };
    nextPriorityList: NextPriorityItem[];
    decisionStatus: string;
    decisionRationale: string;
  }
  
   function determineNextAlgorithmPriority(
    input: DetermineNextAlgorithmPriorityInput
  ): DetermineNextAlgorithmPriorityResult {
    const { metrics, previousPriorityList, improvementHistory } = input;
  
    // 1. 改善成功判定
    const successRateImprovement =
      metrics.successRateAfterImprovement - metrics.successRateBeforeImprovement;
    const improvementSuccessJudgment =
      metrics.successRateAfterImprovement >= metrics.successRateTargetThreshold;
  
    // 2. 調理時間短縮度の達成判定
    const cookingTimeTargetAchieved =
      metrics.cookingTimeShorteningMinutes >= metrics.cookingTimeTargetMinutes;
  
    // 3. ユーザー満足度の改善幅
    const userSatisfactionImprovement =
      metrics.userSatisfactionScoreAfter - metrics.userSatisfactionScoreBefore;
  
    // 4. 総合改善スコア計算
    // (成功率改善 + 満足度改善 + 時間短縮達成フラグ) / 3 * 100
    const timeAchievementBonus = cookingTimeTargetAchieved ? 1 : 0;
    const rawImprovementScore =
      (successRateImprovement + userSatisfactionImprovement + timeAchievementBonus) /
      3 *
      100;
    const overallImprovementScore = Math.min(100, Math.round(rawImprovementScore));
  
    // 5. 次の優先度リスト計算
    const nextPriorityList: NextPriorityItem[] = previousPriorityList.map(
      (item) => {
        let newScore: number;
        if (item.algorithmId === metrics.algorithmId) {
          // 改善成功したアルゴリズムの新スコア
          // 新優先度スコア = (過去の優先度スコア × 0.4) + (改善スコア × 0.6)
          newScore = Math.round(
            item.impactScore * 0.4 + overallImprovementScore * 0.6
          );
        } else {
          // 他のアルゴリズムは基本スコアを維持（若干調整）
          // 相対的に下げるため、基本スコアに0.8を乗じる
          newScore = Math.round(item.impactScore * 0.8);
        }
  
        return {
          algorithmId: item.algorithmId,
          previousPriorityRank: item.priorityRank,
          newPriorityRank: 0, // 後で再計算
          newPriorityScore: newScore,
          impactScoreDelta: newScore - item.impactScore,
        };
      }
    );
  
    // スコアでソートして新しいランクを割り当て
    nextPriorityList.sort((a, b) => b.newPriorityScore - a.newPriorityScore);
    nextPriorityList.forEach((item, index) => {
      item.newPriorityRank = index + 1;
    });
  
    // 6. 根拠情報の構築
    const evidenceData = {
      improvementHistory: improvementHistory,
      evaluationMetrics: {
        successRateChange: successRateImprovement,
        cookingTimeShorteningAchieved: metrics.cookingTimeShorteningMinutes,
        userSatisfactionChange: userSatisfactionImprovement,
        metricsCollectionCount: metrics.evaluationMetricsCount,
      },
      analysisTimestamp: metrics.analysisDate,
    };
  
    // 7. 決定根拠サマリー
    const rationales: string[] = [];
    if (improvementSuccessJudgment) {
      rationales.push("目標値到達");
    }
    if (successRateImprovement > 0) {
      rationales.push("改善成功");
    }
    if (cookingTimeTargetAchieved) {
      rationales.push("調理時間短縮達成");
    }
    if (userSatisfactionImprovement > 0) {
      rationales.push("ユーザー満足度向上");
    }
  
    const decisionRationale =
      rationales.length > 0
        ? rationales.join("、")
        : "改善実績に基づく優先度再評価";
  
    return {
      improvementSuccessJudgment,
      successRateImprovementPoints: successRateImprovement,
      cookingTimeTargetAchieved,
      userSatisfactionImprovement,
      overallImprovementScore,
      evidenceData,
      nextPriorityList,
      decisionStatus: "success",
      decisionRationale,
    };
  }
  return { determineNextAlgorithmPriority };
})();
export const determineNextAlgorithmPriority = __aivicBundle_199_determineNextAlgorithmPriority.determineNextAlgorithmPriority;
