/* AIVIC_FUNCTION_BUNDLE_START owner=calculateAlgorithmImprovementEffect exports=calculateAlgorithmImprovementEffect */
const __aivicBundle_201_calculateAlgorithmImprovementEffect = (() => {
  function calculateAlgorithmImprovementEffect(input: {
    pre_improvement_achievement_rate: number;
    post_improvement_achievement_rate: number;
    pre_improvement_gap_value: number;
    post_improvement_gap_value: number;
  }): {
    achievement_rate_difference: number;
    gap_value_difference: number;
    has_improvement: boolean;
    improvement_status: string;
    improvement_percentage: number;
    status: string;
    error_message: null | string;
  } {
    try {
      const achievement_rate_difference =
        input.post_improvement_achievement_rate -
        input.pre_improvement_achievement_rate;
  
      const gap_value_difference =
        input.post_improvement_gap_value - input.pre_improvement_gap_value;
  
      const has_improvement =
        achievement_rate_difference > 0 || gap_value_difference < 0;
  
      const improvement_percentage =
        input.pre_improvement_achievement_rate !== 0
          ? (achievement_rate_difference /
              input.pre_improvement_achievement_rate) *
            100
          : 0;
  
      const improvement_status = has_improvement
        ? 'improved'
        : 'no_improvement';
  
      return {
        achievement_rate_difference,
        gap_value_difference,
        has_improvement,
        improvement_status,
        improvement_percentage,
        status: 'success',
        error_message: null,
      };
    } catch (error) {
      return {
        achievement_rate_difference: 0,
        gap_value_difference: 0,
        has_improvement: false,
        improvement_status: 'error',
        improvement_percentage: 0,
        status: 'failed',
        error_message:
          error instanceof Error ? error.message : 'Unknown error occurred',
      };
    }
  }
  return { calculateAlgorithmImprovementEffect };
})();
